/* Câu hỏi các đề GDCD lớp 6 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- GDCD 6 · Kiểm tra cuối học kì I (Kết nối tri thức) ----------
     Phạm vi học kì I ghi ở note. Câu tự soạn. Mức độ lv của đề 1 ghi ở Phiên N6 (câu, chủ đề giữ nguyên). Hai đề là kho của đề
     ngẫu nhiên "gdcd6-ck1-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js). Câu ở hai ô
     khác nhau của ma trận có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời giải không ghi sẵn đáp án của câu khác.
     Cách xếp mức (cả hai đề): nêu khái niệm, ý nghĩa, câu tục ngữ, biểu hiện quen thuộc là Biết; nhận ra phẩm chất qua việc làm
     của một bạn, đánh giá một nhận định, phân loại là Hiểu; xử lí tình huống (nên làm gì, lời khuyên nào đúng) là Vận dụng.
     Câu 13 của đề 1 trước hỏi “đức tính nào?” với đáp án “Kiên trì”, trùng nhãn chủ đề hiện trên câu; Phiên N22 hỏi theo chiều khác
     (cho tình huống rồi hỏi nhận xét đúng), giữ chủ đề, mức, dạng câu. */
  "gdcd6-ck1-de1": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, học kì I: Bài 1 Tự hào về truyền thống gia đình, dòng họ; Bài 2 Yêu thương con người; Bài 3 Siêng năng, kiên trì; Bài 4 Tôn trọng sự thật; Bài 5 Tự lập; Bài 6 Tự nhận thức bản thân. Có trường chỉ kiểm tra đến Bài 5, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Truyền thống gia đình, dòng họ là:", o: ["Những giá trị tốt đẹp được gia đình, dòng họ giữ gìn và truyền từ đời này sang đời khác", "Những tài sản, nhà cửa, ruộng vườn, đồ quý mà ông bà, cha mẹ để lại cho con cháu đời sau", "Những quy định riêng mà mỗi gia đình tự đặt ra rồi thay đổi theo từng năm", "Những thói quen sinh hoạt hằng ngày của từng người trong gia đình"], x: "Truyền thống gia đình, dòng họ là những giá trị tốt đẹp như yêu nước, hiếu học, cần cù lao động, giữ nghề truyền thống… được giữ gìn và truyền từ đời này sang đời khác.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Việc làm nào thể hiện sự giữ gìn, phát huy truyền thống gia đình, dòng họ?", o: ["Chăm chỉ học tập để tiếp nối truyền thống hiếu học của gia đình", "Chê nghề truyền thống của gia đình là cũ kĩ, lạc hậu, không nên theo", "Khoe khoang về dòng họ mình để coi thường các bạn khác", "Ngại kể với bạn bè về công việc của bố mẹ"], x: "Giữ gìn truyền thống là tìm hiểu, tự hào và học tập, rèn luyện cho xứng đáng. Chê bai, ngại ngùng hay khoe khoang để coi thường người khác đều là việc làm không đúng.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "tf", q: "Khoe khoang về truyền thống dòng họ để coi thường người khác là biểu hiện của lòng tự hào đúng đắn.", a: false, x: "Tự hào đúng đắn là trân trọng và cố gắng tiếp nối truyền thống tốt đẹp, không phải khoe khoang hay coi thường người khác.", lv: 2 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Gia đình H có nghề làm gốm truyền thống từ nhiều đời. H nên làm gì?", o: ["Tìm hiểu, học nghề và giới thiệu gốm của gia đình với bạn bè", "Không kể với ai vì làm gốm vất vả, lấm lem", "Khuyên bố mẹ bỏ nghề gốm để chuyển sang làm việc khác nhàn hơn", "Không quan tâm vì đó là việc riêng của người lớn"], x: "Tìm hiểu, học hỏi và giới thiệu nghề của gia đình là cách giữ gìn và phát huy truyền thống gia đình, dòng họ.", lv: 3 },
      { topic: "Yêu thương con người", type: "mc", q: "Ý nào nói đúng về lòng yêu thương con người?", o: ["Yêu thương người khác là biết quan tâm, chia sẻ và sẵn lòng giúp đỡ họ, kể cả người không quen biết", "Chỉ cần yêu thương ông bà, cha mẹ, anh chị em trong nhà là đủ", "Giúp đỡ người khác là để được mọi người khen ngợi, chú ý", "Yêu thương bạn là làm theo mọi điều bạn muốn, kể cả việc sai trái"], x: "Yêu thương con người là quan tâm, chia sẻ, giúp đỡ người khác, không chỉ người thân trong nhà. Giúp người vì muốn được khen, hay chiều theo cả việc sai của bạn thì không phải là yêu thương.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Câu tục ngữ nào nói về lòng yêu thương con người?", o: ["Thương người như thể thương thân", "Kiến tha lâu cũng đầy tổ", "Đi một ngày đàng, học một sàng khôn", "Ăn vóc, học hay"], x: "“Thương người như thể thương thân” khuyên ta yêu thương người khác như yêu thương chính bản thân mình.", lv: 1 },
      { topic: "Yêu thương con người", type: "tf", q: "Thờ ơ, vô cảm trước khó khăn của người khác là trái với yêu thương con người.", a: true, x: "Trái với yêu thương con người là thờ ơ, vô cảm, ích kỉ, chỉ biết đến bản thân.", lv: 2 },
      { topic: "Yêu thương con người", type: "mc", q: "Một bạn cùng lớp bị ốm, phải nghỉ học nhiều ngày. Việc làm nào thể hiện lòng yêu thương bạn?", o: ["Đến thăm và chép bài giúp bạn", "Mặc kệ vì đó không phải bạn thân", "Nói với cả lớp rằng bạn giả ốm để trốn học", "Chờ bạn đi học lại rồi mới hỏi thăm qua loa"], x: "Đến thăm, chép bài giúp bạn là quan tâm, chia sẻ khó khăn với bạn.", lv: 3 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Bạn nào dưới đây là người siêng năng?", o: ["Ngày nào Phương cũng tự giác ôn bài, tưới cây, gấp quần áo mà không cần ai nhắc", "Đức hăng hái dọn phòng một buổi rồi bỏ mặc cả tháng sau đó", "Khánh chỉ làm việc nhà khi được mẹ hứa thưởng", "Quân chỉ quét nhà khi có khách đến chơi"], x: "Phương làm việc tự giác, đều đặn mỗi ngày: đó là siêng năng. Làm một lần rồi bỏ, chờ được thưởng hay có khách mới làm đều chưa phải là siêng năng.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Việc làm nào thể hiện tính kiên trì?", o: ["Thu luyện viết chữ đẹp suốt ba tháng, có lúc viết mãi chưa đẹp, mỏi tay nhưng vẫn không bỏ", "Bình đang giải câu đố thì thấy khó, bỏ sang trò chơi khác cho đỡ mệt", "Lâm nhờ anh trai giải hộ phần bài khó", "Hiền làm bài vội cho xong, sai cũng được"], x: "Thu gặp khó khăn, có lúc mệt nhưng vẫn quyết làm đến cùng: đó là kiên trì. Bỏ dở khi gặp khó, nhờ người khác làm hộ hay làm vội cho xong đều trái với kiên trì.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "fill", q: "Hoàn thành câu tục ngữ nói về tính kiên trì: “Có công mài sắt, có ngày nên ___.”", ans: ["kim"], x: "“Có công mài sắt, có ngày nên kim”: kiên trì, bền bỉ thì việc khó đến đâu cũng làm được.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "tf", q: "Người siêng năng chỉ chăm chỉ làm những việc mình thích.", a: false, x: "Siêng năng là tự giác, cần cù với mọi việc cần làm, kể cả những việc khó hoặc chưa thích.", lv: 2 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Anh Tuấn học nghề sửa xe máy. Lúc đầu anh làm hỏng nhiều, nhưng ngày nào anh cũng tập, hỏi thầy từng chút. Hai năm sau, anh mở được tiệm sửa xe, được nhiều người tin. Câu chuyện cho thấy điều gì?", o: ["Chăm tập luyện, không nản lòng giúp anh Tuấn giỏi nghề", "Anh Tuấn giỏi nghề chủ yếu là nhờ gặp may mắn", "Học nghề không cần chăm chỉ, chỉ cần khéo tay là đủ", "Ai làm hỏng nhiều lúc đầu thì không nên theo nghề đó"], x: "Nhờ chăm tập mỗi ngày và không bỏ cuộc khi làm hỏng, anh Tuấn dần thành thạo nghề, được mọi người tin cậy. Thành công đến từ sự cố gắng bền bỉ, không phải từ may mắn.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Thấy bạn Tuấn bị nghi là đã lấy chiếc bút của Ngân, Hà kể với cô rằng mình đã thấy chiếc bút rơi ở góc lớp. Việc Hà nói đúng điều mình thấy đã giúp:", o: ["Bạn Tuấn không bị nghi oan", "Hà được cô cho điểm cao hơn", "Ngân được cô tặng thêm bút mới", "Tuấn bị cô phạt nặng hơn"], x: "Hà nói đúng điều mình đã thấy nên cô biết Tuấn không lấy bút, Tuấn không bị nghi oan. Nói đúng sự thật giúp mọi việc được hiểu đúng và mọi người tin nhau hơn.", lv: 1 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Hành vi nào thể hiện tôn trọng sự thật?", o: ["Nhận lỗi với cô giáo khi mình làm vỡ lọ hoa của lớp", "Đổ lỗi cho bạn ngồi bên cạnh để mình không bị cô phạt", "Sửa điểm trong vở trước khi đưa bố mẹ xem", "Bịa ra lí do bị ốm để được nghỉ học"], x: "Dám nhận lỗi là nói đúng sự thật. Đổ lỗi cho bạn, sửa điểm, bịa chuyện đều là che giấu, làm sai lệch sự thật.", lv: 1 },
      { topic: "Tôn trọng sự thật", type: "tf", q: "Khi bạn thân làm sai, ta nên che giấu giúp bạn để giữ tình bạn.", a: false, x: "Bao che cho cái sai là không tôn trọng sự thật. Người bạn tốt nên khuyên bạn nhận lỗi và sửa sai.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Câu tục ngữ nào nói về sống ngay thẳng, tôn trọng sự thật?", o: ["Cây ngay không sợ chết đứng", "Một con ngựa đau, cả tàu bỏ cỏ", "Kiến tha lâu cũng đầy tổ", "Uống nước nhớ nguồn"], x: "“Cây ngay không sợ chết đứng”: người ngay thẳng, sống đúng sự thật thì không sợ bị nghi oan.", lv: 2 },
      { topic: "Tự lập", type: "mc", q: "Việc làm nào dưới đây TRÁI với tính tự lập?", o: ["Việc gì hơi khó cũng chờ bố mẹ, anh chị làm hộ", "Tự lên kế hoạch ôn bài trước kì kiểm tra", "Tự giặt khăn quàng, tất của mình", "Tự dọn bàn học sau khi học xong"], x: "Chờ người khác làm hộ là ỷ lại, dựa dẫm, trái với tự lập. Tự ôn bài, tự giặt đồ nhỏ, tự dọn bàn học là tự làm lấy việc của mình.", lv: 1 },
      { topic: "Tự lập", type: "mc", q: "Câu tục ngữ nào nói về tính tự lập?", o: ["Muốn ăn thì lăn vào bếp", "Lá lành đùm lá rách", "Uống nước nhớ nguồn", "Mất lòng trước, được lòng sau"], x: "“Muốn ăn thì lăn vào bếp”: muốn có gì thì phải tự mình làm lấy, không trông chờ người khác.", lv: 2 },
      { topic: "Tự lập", type: "tf", q: "Người tự lập không bao giờ nhận sự giúp đỡ của người khác.", a: false, x: "Tự lập không có nghĩa là từ chối mọi sự giúp đỡ. Ta vẫn hợp tác và nhận sự giúp đỡ chính đáng khi thật sự cần, nhưng không ỷ lại.", lv: 2 },
      { topic: "Tự lập", type: "mc", q: "Việc làm nào thể hiện tính tự lập của học sinh lớp 6?", o: ["Tự soạn sách vở, chuẩn bị đồ dùng học tập cho ngày hôm sau", "Nhờ mẹ làm hộ bài tập thủ công để được điểm cao hơn các bạn", "Chép bài giải của bạn cho nhanh", "Chờ bố mẹ gọi mới dậy đi học dù đã có đồng hồ báo thức"], x: "Tự chuẩn bị sách vở, đồ dùng là tự làm việc của mình. Nhờ mẹ làm hộ, chép bài của bạn, chờ bố mẹ gọi dậy là dựa dẫm, ỷ lại.", lv: 1 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "Bạn nào dưới đây đã tự nhận thức đúng về bản thân?", o: ["Nam nói: “Mình đọc diễn cảm hay nhưng tính nhẩm còn chậm, mình cần luyện tính nhẩm mỗi ngày.”", "Phong nói: “Mình giỏi nhất lớp ở mọi môn, chẳng cần cố gắng thêm.”", "Thảo nói: “Mình chẳng làm được việc gì cho ra hồn.”", "Đạt nói: “Ai bảo mình thế nào thì mình là thế ấy.”"], x: "Nam nhìn ra cả điểm mạnh (đọc diễn cảm) và điểm yếu (tính nhẩm chậm) của mình, rồi biết cần làm gì. Tự đề cao mình, tự coi thường mình hay nghe theo mọi lời người khác đều chưa phải là tự nhận thức đúng về bản thân.", lv: 1 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "Cách nào giúp bạn tự nhận thức đúng về bản thân?", o: ["Lắng nghe nhận xét của thầy cô, bạn bè và tự suy ngẫm về mình", "Chỉ nghe lời khen của mọi người, bỏ qua tất cả các lời góp ý", "Không quan tâm người khác nói gì về mình", "Luôn so bì với các bạn trong lớp để thấy mình hơn mọi người"], x: "Muốn hiểu đúng về mình, cần tự suy ngẫm và lắng nghe nhận xét của người khác, cả lời khen lẫn lời góp ý.", lv: 2 },
      { topic: "Tự nhận thức bản thân", type: "tf", q: "Biết mình hay nóng nảy, Tùng tập hít thở sâu và đếm đến mười trước khi trả lời mỗi khi bị bạn trêu. Tùng đã dựa vào hiểu biết về bản thân để khắc phục điểm yếu của mình.", a: true, x: "Đúng. Tùng nhận ra điểm yếu của mình (hay nóng nảy) và tìm cách sửa. Hiểu đúng về bản thân giúp ta biết điều gì cần phát huy, điều gì cần khắc phục.", lv: 2 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "H hát hay nhưng còn rụt rè khi phát biểu trước lớp. H nên làm gì?", o: ["Tham gia văn nghệ của lớp và tập dần cách nói trước đông người", "Không bao giờ giơ tay phát biểu trong giờ học để khỏi thấy ngại", "Nghĩ rằng mình chẳng làm được việc gì", "Đòi các bạn phải khen mình hát hay"], x: "H biết mình hát hay (điểm mạnh) và còn rụt rè (điểm yếu). Tham gia văn nghệ và tập nói trước lớp giúp H phát huy điểm mạnh, khắc phục điểm yếu.", lv: 3 }
    ]
  },

  /* Đề 2 (Phiên N6): cùng phạm vi, đủ 6 chủ đề của đề 1 (chữ chủ đề giữ nguyên), chia đúng theo ma trận của đề ngẫu nhiên:
     10 Biết, 8 Hiểu, 7 Vận dụng (đề 1 có 12 – 10 – 3, nên đề 2 có câu xử lí tình huống ở cả 6 bài). Dạng câu theo khung Công văn
     7991: nhiều lựa chọn, đúng/sai 4 ý về một tình huống, điền (tục ngữ, thành ngữ), nối cột (việc làm – phẩm chất). */
  "gdcd6-ck1-de2": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, học kì I: Bài 1 Tự hào về truyền thống gia đình, dòng họ; Bài 2 Yêu thương con người; Bài 3 Siêng năng, kiên trì; Bài 4 Tôn trọng sự thật; Bài 5 Tự lập; Bài 6 Tự nhận thức bản thân. Có trường chỉ kiểm tra đến Bài 5, phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Truyền thống gia đình, dòng họ", type: "fill", q: "Hoàn thành câu tục ngữ nói về truyền thống của gia đình, dòng họ: “Con nhà tông, không giống lông cũng giống ___.”", ans: ["cánh"], x: "Câu tục ngữ ý nói con cháu thường mang những nét giống ông bà, cha mẹ về tính nết, tài năng, nghề nghiệp.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Điều nào sau đây KHÔNG phải là truyền thống tốt đẹp của gia đình, dòng họ?", o: ["Quan niệm trọng nam khinh nữ", "Con cháu hiếu thảo với ông bà, cha mẹ", "Anh chị em đoàn kết, nhường nhịn nhau", "Sống trung thực, giữ lời hứa"], x: "Trọng nam khinh nữ là quan niệm lạc hậu, cần bỏ. Hiếu thảo, đoàn kết, trung thực là những truyền thống tốt đẹp cần giữ gìn.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Dòng họ của Minh có nhiều đời làm nón lá. Đó là truyền thống nào của dòng họ?", o: ["Truyền thống nghề nghiệp", "Truyền thống hiếu học", "Truyền thống yêu nước", "Truyền thống thể thao"], x: "Nhiều thế hệ trong dòng họ cùng làm một nghề và truyền lại cho con cháu là truyền thống nghề nghiệp.", lv: 2 },
      { topic: "Truyền thống gia đình, dòng họ", type: "tf4", q: "Gia đình Hùng có nghề gói bánh chưng truyền thống. Mỗi việc làm sau của Hùng đúng hay sai?", o: ["Hùng phụ bố mẹ rửa lá dong, vo gạo và học cách gói bánh.", "Hùng ngại, không muốn các bạn biết nhà mình làm bánh chưng.", "Hùng mang bánh của gia đình đến giới thiệu ở hội chợ Tết của trường.", "Hùng cho rằng chỉ người lớn mới cần giữ nghề của gia đình."], a: [true, false, true, false], x: "a), c) Đúng: học nghề và giới thiệu sản phẩm của gia đình là góp phần giữ nghề truyền thống. b), d) Sai: ngại ngùng hay đẩy việc cho người lớn là chưa trân trọng nghề của gia đình; học sinh cũng góp phần được bằng những việc vừa sức.", lv: 3 },
      { topic: "Yêu thương con người", type: "mc", q: "Việc làm nào sau đây thể hiện lòng yêu thương con người?", o: ["Nhường áo ấm cho bạn có hoàn cảnh khó khăn", "Trêu chọc một bạn bị khuyết tật", "Không chơi với bạn mới chuyển đến lớp", "Tranh giành đồ chơi với em nhỏ"], x: "Nhường áo ấm cho bạn đang gặp khó khăn là việc làm xuất phát từ lòng yêu thương. Trêu chọc, xa lánh, tranh giành làm người khác buồn và tổn thương.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Người biết yêu thương người khác thường nhận được điều gì?", o: ["Được mọi người yêu quý, kính trọng", "Được người khác làm hộ mọi việc", "Không bao giờ gặp khó khăn", "Luôn được nhận nhiều quà tặng"], x: "Yêu thương con người giúp mọi người gắn bó với nhau. Người biết yêu thương người khác sẽ được mọi người yêu quý, kính trọng.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Trong lớp, Hà hay bắt chước giọng của một bạn nói ngọng để trêu cho cả lớp cười. Việc làm của Hà:", o: ["Làm bạn bị tổn thương, thiếu tôn trọng người khác", "Là trò đùa vui, không làm ảnh hưởng gì đến bạn ấy", "Giúp bạn nhận ra lỗi phát âm để sửa nhanh hơn", "Cho thấy Hà là người tự tin, mạnh dạn trước lớp"], x: "Chế giễu khuyết điểm của người khác làm bạn bị tổn thương, xấu hổ. Đó là việc làm thiếu tôn trọng, trái với yêu thương con người.", lv: 2 },
      { topic: "Yêu thương con người", type: "mc", q: "Trên đường đi học về, Nam thấy một cụ già muốn sang đường nhưng xe cộ qua lại đông. Nam nên làm gì?", o: ["Dắt cụ qua đường cẩn thận hoặc nhờ người lớn giúp", "Đứng xem cụ tự sang đường rồi mới đi tiếp", "Rung chuông xe đạp giục cụ đi nhanh hơn", "Đi tiếp vì cụ không phải người quen"], x: "Giúp đỡ người già, người gặp khó khăn bằng việc làm vừa sức là thể hiện lòng yêu thương con người. Nếu thấy không an toàn, Nam nên nhờ người lớn cùng giúp.", lv: 3 },
      { topic: "Siêng năng, kiên trì", type: "fill", q: "Hoàn thành câu tục ngữ: “Nước chảy đá ___.”", ans: ["mòn"], x: "Dòng nước chảy mãi cũng làm đá mòn đi: làm việc gì mà bền bỉ, không bỏ cuộc thì sẽ thành công.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Câu tục ngữ nào khuyên chúng ta chăm chỉ lao động?", o: ["Tay làm hàm nhai, tay quai miệng trễ", "Gần mực thì đen, gần đèn thì rạng", "Tốt gỗ hơn tốt nước sơn", "Ăn quả nhớ kẻ trồng cây"], x: "“Tay làm hàm nhai, tay quai miệng trễ”: chịu khó làm thì có cái ăn, khoanh tay ngồi không thì chịu đói. Câu tục ngữ khuyên chúng ta siêng năng lao động.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "match", q: "Nối mỗi việc làm với phẩm chất mà việc làm đó thể hiện.", l: ["Ngày nào Mai cũng quét nhà, rửa bát giúp mẹ", "Nam tập đi xe đạp, ngã nhiều lần vẫn tập tiếp đến khi đi được", "Hùng để bài tập dồn đến sáng hôm nộp mới làm", "Gặp bài văn khó, Lan bỏ dở, quay sang xem ti vi"], r: ["Siêng năng", "Kiên trì", "Lười biếng", "Ngại khó, nản chí"], x: "Mai ngày nào cũng làm việc nhà: siêng năng. Nam không bỏ cuộc dù bị ngã: kiên trì. Hùng dồn việc đến phút cuối: lười biếng. Lan gặp khó là bỏ: ngại khó, nản chí.", lv: 2 },
      { topic: "Siêng năng, kiên trì", type: "tf4", q: "Minh đặt mục tiêu mỗi ngày đọc 10 trang sách, nhưng mới được ba hôm đã thấy chán. Mỗi lời khuyên sau dành cho Minh đúng hay sai?", o: ["Đọc vào một giờ cố định mỗi ngày, mỗi lần đọc một ít.", "Bỏ luôn vì đọc sách không hợp với mình.", "Chọn sách mình thích, rủ bạn cùng đọc để giữ hứng thú.", "Nghỉ cả tuần rồi đọc dồn một lần vào Chủ nhật."], a: [true, false, true, false], x: "a), c) Đúng: mỗi ngày đọc một ít vào giờ cố định, chọn sách hay giúp Minh giữ được thói quen tốt. b) Sai: Minh nên tìm cách đọc cho vui hơn chứ không nên bỏ ngay. d) Sai: đọc dồn một lần dễ mệt, khó giữ thói quen.", lv: 3 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Câu tục ngữ nào sau đây nói về tôn trọng sự thật?", o: ["Nói có sách, mách có chứng", "Một cây làm chẳng nên non", "Học thầy không tày học bạn", "Ăn quả nhớ kẻ trồng cây"], x: "“Nói có sách, mách có chứng”: nói điều gì cũng phải có bằng chứng, đúng với sự thật.", lv: 1 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Việc làm nào sau đây là trái với tôn trọng sự thật?", o: ["Chia sẻ lên mạng xã hội một tin chưa rõ đúng sai", "Kể lại đúng những gì mình đã nhìn thấy", "Hỏi lại người lớn khi chưa chắc một thông tin", "Ghi đúng số liệu đo được trong giờ thực hành"], x: "Vội chia sẻ một tin chưa rõ đúng sai có thể làm lan truyền điều không đúng sự thật, gây hại cho người khác. Ba việc còn lại đều tôn trọng sự thật.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "tf4", q: "Mỗi ý sau đúng hay sai?", o: ["Cô chấm nhầm, cộng thừa điểm cho Hoa; Hoa báo lại để cô sửa. Hoa đã tôn trọng sự thật.", "Bình chép bài của bạn rồi nói với mẹ là tự làm. Bình đã tôn trọng sự thật.", "Bị điểm kém, Tâm giấu bài và nói với mẹ là cô chưa trả. Tâm đã tôn trọng sự thật.", "Bài kiểm tra chưa được điểm cao nhưng Khoa vẫn kể đúng kết quả với bố mẹ. Khoa đã tôn trọng sự thật."], a: [true, false, false, true], x: "a), d) Đúng: Hoa và Khoa nói đúng sự thật dù điều đó không có lợi cho mình. b), c) Sai: Bình và Tâm nói dối bố mẹ.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Bài thuyết trình của tổ được cô khen, nhưng phần lớn bài do Quyên tìm tư liệu và viết. Cô hỏi ai đã làm phần đó. Lan là tổ trưởng, Lan nên trả lời thế nào?", o: ["Nói rõ phần đó chủ yếu do Quyên làm", "Nhận là mình làm để được cô khen", "Im lặng vì đằng nào cả tổ cũng được khen", "Nói rằng cả tổ làm đều như nhau"], x: "Nói đúng người đã làm là tôn trọng sự thật và công bằng với bạn. Nhận công của bạn hay nói sai đi đều là không tôn trọng sự thật.", lv: 3 },
      { topic: "Tự lập", type: "fill", q: "Hoàn thành thành ngữ chê người lười biếng: “Há miệng chờ ___.”", ans: ["sung"], x: "“Há miệng chờ sung” chê người lười biếng, chỉ ngồi chờ may mắn mà không chịu làm. Lối sống đó trái với tính tự lập.", lv: 1 },
      { topic: "Tự lập", type: "mc", q: "Rèn luyện tính tự lập giúp chúng ta:", o: ["Tự tin, trưởng thành, dễ thành công trong cuộc sống", "Có thật nhiều tiền mà không cần phải làm việc gì", "Được mọi người trong nhà làm hộ hết mọi việc", "Không phải đi học, không cần học hỏi thêm nữa"], x: "Người có tính tự lập thường tự tin, bản lĩnh, dám đương đầu với thử thách, nên dễ thành công và được mọi người tôn trọng.", lv: 1 },
      { topic: "Tự lập", type: "mc", q: "Hưng không bao giờ học nhóm và không muốn ai giúp mình, kể cả khi gặp bài quá khó. Hưng cho rằng như vậy mới là tự lập. Nhận xét nào về Hưng là đúng?", o: ["Hưng hiểu chưa đúng: người tự lập vẫn nhận giúp đỡ khi thật sự cần", "Hưng hiểu đúng: người tự lập không bao giờ nhờ ai giúp đỡ", "Hưng là người ỷ lại, việc gì cũng trông vào bạn bè", "Hưng là người thiếu trung thực, hay nói dối bạn bè"], x: "Tự lập không có nghĩa là làm mọi việc một mình, từ chối mọi sự giúp đỡ. Khi gặp việc quá sức, ta vẫn nên học hỏi, hợp tác và nhận giúp đỡ chính đáng, miễn là không ỷ lại.", lv: 2 },
      { topic: "Tự lập", type: "tf4", q: "Lớp tổ chức cắm trại hai ngày ở ngoại thành. Mỗi việc làm sau thể hiện tính tự lập đúng hay sai?", o: ["Tự gấp chăn, xếp gọn chỗ ngủ của mình.", "Gọi điện nhờ bố mẹ đến dọn lều giúp.", "Tự giữ gìn đồ dùng cá nhân, không để thất lạc.", "Khóc đòi về nhà ngay vì không quen ngủ xa nhà."], a: [true, false, true, false], x: "a), c) Đúng: đó là những việc bạn tự làm được khi xa nhà. b), d) Sai: nhờ bố mẹ dọn giúp hay đòi về ngay là còn ỷ lại vào người lớn.", lv: 3 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "Tự đánh giá đúng khả năng của mình giúp bạn:", o: ["Đặt mục tiêu, kế hoạch học tập vừa sức", "Không bao giờ mắc lỗi khi làm bài", "Luôn giỏi hơn mọi người xung quanh", "Được mọi người khen ngợi ở mọi lúc"], x: "Hiểu đúng khả năng của mình thì đặt được mục tiêu vừa sức và có kế hoạch học tập phù hợp.", lv: 1 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "Mai rất thích nấu ăn nhưng nấu chưa ngon; Mai vẽ rất đẹp nhưng lại không thích vẽ lắm. Nhận xét nào về Mai là đúng?", o: ["Nấu ăn là sở thích, còn vẽ là khả năng của Mai", "Nấu ăn là khả năng, còn vẽ là sở thích của Mai", "Mai không có khả năng nào cả", "Sở thích và khả năng của Mai là một"], x: "Sở thích là điều mình thích làm, khả năng là điều mình làm tốt. Mai thích nấu ăn (sở thích) và vẽ đẹp (khả năng). Sở thích và khả năng của một người có thể khác nhau.", lv: 2 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "Tham gia các câu lạc bộ, đội nhóm ở trường như cờ vua, bóng đá, làm báo tường giúp gì cho việc tự nhận thức bản thân?", o: ["Giúp bạn phát hiện thêm khả năng, sở thích của mình", "Giúp bạn không cần học các môn văn hóa nữa", "Giúp bạn lúc nào cũng đạt giải thưởng cao nhất", "Không giúp gì cho việc hiểu rõ bản thân mình"], x: "Thử sức ở nhiều hoạt động khác nhau giúp bạn khám phá thêm những điều mới về bản thân.", lv: 2 },
      { topic: "Tự nhận thức bản thân", type: "mc", q: "Lan làm toán nhanh nhưng hay cẩu thả, bài kiểm tra thường mất điểm vì tính sai. Lan nên làm gì?", o: ["Làm xong thì dành thời gian soát lại từng bước tính", "Làm thật nhanh để nộp bài sớm nhất lớp", "Cho rằng mình giỏi nên không cần cẩn thận", "Bỏ qua những bài dài để khỏi tính sai"], x: "Lan làm nhanh nhưng hay sai vì cẩu thả. Dành thời gian soát lại từng bước giúp Lan bớt sai mà vẫn làm kịp giờ.", lv: 3 },
      { topic: "Tự nhận thức bản thân", type: "tf4", q: "Trường tổ chức giải bóng đá. Khôi chạy rất nhanh nhưng sút bóng chưa chuẩn, và Khôi muốn được vào đội của lớp. Mỗi lời khuyên sau dành cho Khôi đúng hay sai?", o: ["Đăng kí vào đội và tập thêm sút bóng mỗi chiều.", "Bỏ ý định vì nghĩ mình chẳng giỏi gì.", "Xin chơi ở vị trí cần chạy nhanh, hợp với khả năng của mình.", "Đòi làm đội trưởng để được các bạn chú ý."], a: [true, false, true, false], x: "a), c) Đúng: Khôi chọn vị trí hợp với khả năng và chăm tập phần còn yếu. b) Sai: Khôi có điểm mạnh là chạy nhanh, không nên bỏ cuộc. d) Sai: muốn được chú ý không phải lí do để làm đội trưởng.", lv: 3 }
    ]
  },

  /* ---------- GDCD 6 · Kiểm tra giữa học kì I (Kết nối tri thức) ----------
     Phạm vi nửa đầu học kì I, ghi ở note. Câu tự soạn. Mức độ lv của đề 1 ghi ở Phiên N24b (câu, chủ đề giữ nguyên), cách xếp mức
     như đề cuối kì I ở trên. Hai đề là kho của đề ngẫu nhiên "gdcd6-gk1-ngau-nhien" (không có câu riêng nên không ghi vào file này;
     ma trận ở data/banks/index.js). Câu ở hai ô khác nhau của ma trận có thể cùng được rút vào một đề, nên đề bài, các lựa chọn,
     lời giải không ghi sẵn đáp án của câu khác; đáp án không trùng chữ chủ đề (nhãn trên câu). */
  "gdcd6-gk1-de1": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, nửa đầu học kì I: Bài 1 Tự hào về truyền thống gia đình, dòng họ; Bài 2 Yêu thương con người; Bài 3 Siêng năng, kiên trì; Bài 4 Tôn trọng sự thật. Có trường chỉ kiểm tra đến Bài 3, phụ huynh đối chiếu với đề cương của trường. Có lời giải từng câu.",
    questions: [
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Đâu là một truyền thống tốt đẹp của gia đình, dòng họ?", o: ["Hiếu học, nhiều đời con cháu chăm chỉ học hành", "Rượu chè, cờ bạc trong những dịp lễ tết", "Thích khoe khoang và chê bai người khác", "Ngại khó, ngại khổ, ỷ lại vào người khác"], x: "Truyền thống tốt đẹp là những giá trị đáng tự hào được giữ gìn qua nhiều đời: hiếu học, cần cù lao động, yêu nước, giữ nghề truyền thống… Thói quen xấu không phải truyền thống đáng tự hào.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Truyền thống gia đình, dòng họ có ý nghĩa gì với mỗi người?", o: ["Tiếp thêm kinh nghiệm và động lực để vượt qua khó khăn", "Giúp ta được hưởng nhiều tài sản hơn người khác", "Giúp ta không cần cố gắng mà vẫn thành công", "Cho ta lí do để coi thường người khác"], x: "Truyền thống gia đình, dòng họ là chỗ dựa, tiếp thêm kinh nghiệm và động lực cho mỗi người, góp phần làm phong phú truyền thống, bản sắc của dân tộc Việt Nam.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "fill", q: "Hoàn thành câu ca dao: “Con người có tổ có tông, Như cây có cội như sông có ___.”", ans: ["nguồn"], x: "Câu ca dao nhắc mỗi người đều có tổ tiên, cội nguồn, cần biết ơn và giữ gìn truyền thống của gia đình, dòng họ.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "tf", q: "Tìm hiểu truyền thống của gia đình, dòng họ qua lời kể của ông bà, cha mẹ là việc nên làm.", a: true, x: "Đúng. Có hiểu truyền thống thì mới biết tự hào và giữ gìn, phát huy truyền thống đó.", lv: 2 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Ông nội của K từng là bộ đội bảo vệ Tổ quốc. Việc làm nào của K thể hiện sự tự hào đúng đắn về truyền thống gia đình?", o: ["Nghe ông kể chuyện, giữ gìn kỉ vật và cố gắng học tập, rèn luyện", "Khoe với các bạn để bắt các bạn phải nghe theo mình", "Cho rằng nhà mình có công nên không cần học hành", "Mang huân chương của ông đến lớp để đổi lấy đồ chơi"], x: "Tự hào đúng đắn là trân trọng, giữ gìn và tiếp nối truyền thống bằng việc làm tốt của mình, không khoe khoang hay ỷ lại.", lv: 3 },
      { topic: "Truyền thống gia đình, dòng họ", type: "tf", q: "Học sinh lớp 6 còn nhỏ nên chưa thể góp phần giữ gìn truyền thống gia đình, dòng họ.", a: false, x: "Sai. Học sinh góp phần được bằng những việc vừa sức: chăm học, ngoan ngoãn, tìm hiểu và kể lại truyền thống gia đình, học nghề truyền thống…", lv: 2 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Việc làm nào chưa thể hiện sự trân trọng truyền thống gia đình, dòng họ?", o: ["Không muốn nghe ông bà kể chuyện về gia đình, dòng họ", "Hỏi ông bà về những người học giỏi trong dòng họ", "Cùng bố mẹ đi viếng mộ ông bà, tổ tiên", "Học nghề thêu truyền thống với bà nội"], x: "Thờ ơ, không muốn tìm hiểu về gia đình, dòng họ là chưa trân trọng truyền thống. Ba việc còn lại đều thể hiện sự trân trọng, giữ gìn truyền thống.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Yêu thương con người có ý nghĩa gì?", o: ["Giúp mọi người gắn bó với nhau, làm cho xã hội tốt đẹp hơn", "Giúp bản thân nhận được nhiều quà tặng hơn", "Khiến người được giúp phải nghe theo mình", "Giúp ta được khen mà không cần cố gắng"], x: "Yêu thương con người giúp mọi người gắn bó, xã hội tốt đẹp hơn. Người biết yêu thương người khác được mọi người yêu quý, kính trọng.", lv: 1 },
      { topic: "Yêu thương con người", type: "fill", q: "Hoàn thành câu tục ngữ nói về lòng yêu thương: “Lá lành đùm lá ___.”", ans: ["rách"], x: "“Lá lành đùm lá rách” khuyên người có điều kiện hơn giúp đỡ, chia sẻ với người gặp khó khăn.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Hành vi nào trái với yêu thương con người?", o: ["Chế giễu một bạn vì nhà bạn nghèo", "Nhường chỗ ngồi cho cụ già trên xe buýt", "Góp sách vở cũ tặng các bạn vùng lũ", "Dắt em nhỏ qua đường"], x: "Chế giễu người có hoàn cảnh khó khăn là thiếu tôn trọng, trái với yêu thương con người. Ba việc còn lại đều thể hiện sự quan tâm, giúp đỡ người khác.", lv: 1 },
      { topic: "Yêu thương con người", type: "tf", q: "Yêu thương con người là truyền thống quý báu của dân tộc Việt Nam.", a: true, x: "Đúng. Truyền thống này thể hiện qua nhiều câu tục ngữ, ca dao và qua các phong trào giúp đỡ người gặp khó khăn.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Trên đường đi học, M thấy một em nhỏ bị lạc, đang khóc tìm mẹ. M nên làm gì?", o: ["Hỏi han, dỗ dành em và nhờ người lớn hoặc công an giúp tìm mẹ", "Đi tiếp vì sợ muộn học, việc đó không liên quan đến mình", "Đứng xem rồi chụp ảnh em bé đăng lên mạng", "Bảo em tự đi tìm mẹ một mình"], x: "Quan tâm, giúp đỡ người gặp khó khăn là yêu thương con người. Với việc quá sức mình như tìm người lạc, nên nhờ người lớn, công an giúp.", lv: 3 },
      { topic: "Yêu thương con người", type: "mc", q: "Bạn H bị đau chân, phải chống nạng đi học. Các bạn trong lớp nên làm gì?", o: ["Giúp H mang cặp, đi cùng H khi lên xuống cầu thang", "Bắt chước dáng đi của H cho cả lớp cười", "Không chơi cùng H vì H đi lại chậm", "Mặc kệ H vì đã có thầy cô lo"], x: "Giúp đỡ bạn đang gặp khó khăn bằng những việc vừa sức là biểu hiện của yêu thương con người.", lv: 3 },
      { topic: "Yêu thương con người", type: "tf", q: "Chỉ người giàu có mới thể hiện được lòng yêu thương con người.", a: false, x: "Sai. Ai cũng thể hiện được lòng yêu thương bằng việc làm phù hợp: hỏi thăm, động viên, giúp một việc nhỏ… không cần phải giàu có.", lv: 2 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Biểu hiện nào trái với siêng năng, kiên trì?", o: ["Gặp bài khó là bỏ, chờ bạn giải xong rồi chép", "Tự giác ôn bài mỗi tối dù không ai nhắc", "Tập đàn đều đặn mỗi ngày", "Làm lại bài nhiều lần cho đến khi đúng"], x: "Ngại khó, nản chí, dựa dẫm vào người khác là trái với siêng năng, kiên trì.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "fill", q: "Hoàn thành câu tục ngữ: “Siêng làm thì có, siêng học thì ___.”", ans: ["hay"], x: "Câu tục ngữ khuyên chăm chỉ làm việc thì có của cải, chăm chỉ học tập thì giỏi giang.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Câu tục ngữ nào nói về sự kiên trì?", o: ["Nước chảy đá mòn", "Uống nước nhớ nguồn", "Lá lành đùm lá rách", "Ăn quả nhớ kẻ trồng cây"], x: "Nước chảy mãi thì đá cũng mòn: làm bền bỉ thì việc khó mấy cũng xong. Các câu còn lại nói về lòng biết ơn và yêu thương con người.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Siêng năng, kiên trì có ý nghĩa gì?", o: ["Giúp con người thành công trong học tập, công việc và cuộc sống", "Giúp con người không bao giờ gặp khó khăn", "Giúp con người làm việc mà không cần nghỉ ngơi", "Giúp con người luôn được người khác làm hộ việc"], x: "Siêng năng, kiên trì giúp con người hoàn thành công việc, thành công trong cuộc sống và được mọi người tin yêu.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "tf", q: "Siêng năng, kiên trì là làm việc liên tục, không nghỉ ngơi, kể cả khi đang ốm mệt.", a: false, x: "Sai. Siêng năng, kiên trì không phải làm quá sức. Cần nghỉ ngơi hợp lí để giữ sức khỏe và làm việc hiệu quả.", lv: 2 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Q muốn bơi giỏi nhưng mới tập vài buổi đã thấy mệt và muốn bỏ. Lời khuyên nào phù hợp nhất với Q?", o: ["Đặt mục tiêu nhỏ, tập đều mỗi tuần, tiến bộ từng chút một", "Bỏ ngay vì bơi lội không hợp với mình", "Chỉ đi bơi vào hôm nào thấy thích", "Tập thật nhiều trong một ngày để giỏi ngay"], x: "Kiên trì là quyết tâm làm đến cùng dù gặp khó khăn. Chia nhỏ mục tiêu và tập đều đặn giúp Q không nản và tiến bộ dần.", lv: 3 },
      { topic: "Siêng năng, kiên trì", type: "tf", q: "Câu ca dao “Ăn no rồi lại nằm khoèo, Nghe giục trống chèo bế bụng đi xem” khen người siêng năng.", a: false, x: "Sai. Câu ca dao chê người lười biếng: ăn no rồi nằm, không chịu làm, nghe có hội thì đi chơi ngay.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Tôn trọng sự thật có ý nghĩa gì?", o: ["Giúp ta được mọi người tin tưởng, quý trọng", "Giúp ta không bao giờ phải nhận lỗi", "Giúp ta luôn được điểm cao", "Giúp ta tránh được mọi lời góp ý"], x: "Tôn trọng sự thật giúp con người nâng cao phẩm giá, được mọi người tin tưởng, quý trọng, và góp phần làm cho xã hội lành mạnh.", lv: 1 },
      { topic: "Tôn trọng sự thật", type: "fill", q: "Hoàn thành câu tục ngữ: “Thuốc đắng dã tật, sự thật mất ___.”", ans: ["lòng"], x: "Lời nói thật có thể làm người nghe khó chịu lúc đầu, nhưng giúp họ nhận ra cái sai để sửa, như thuốc đắng chữa được bệnh.", lv: 1 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Mẹ hỏi bài kiểm tra Toán tuần này của H được mấy điểm. H bị điểm kém. H nên làm gì?", o: ["Nói thật với mẹ và hứa sẽ ôn tập chăm hơn", "Nói rằng cô giáo chưa trả bài", "Giấu bài kiểm tra vào đáy cặp", "Bảo rằng cô giáo chấm nhầm"], x: "Nói thật, nhận ra thiếu sót và tìm cách sửa là tôn trọng sự thật. Giấu giếm hay bịa lí do là trái với tôn trọng sự thật.", lv: 3 },
      { topic: "Tôn trọng sự thật", type: "tf", q: "Khi chưa biết rõ một tin là đúng hay sai, ta không nên vội chia sẻ tin đó cho người khác.", a: true, x: "Đúng. Tôn trọng sự thật cũng là không lan truyền tin chưa rõ đúng sai, nhất là trên mạng xã hội, vì có thể gây hại cho người khác.", lv: 2 }
    ]
  },

  /* Đề 2 (Phiên N24b): cùng phạm vi Bài 1–4, đủ 4 chủ đề của đề 1 (chữ chủ đề giữ nguyên), chia đúng theo ma trận của đề ngẫu
     nhiên: 10 Biết, 8 Hiểu, 7 Vận dụng (đề 1 có 14 – 6 – 5, nên đề 2 có câu xử lí tình huống ở cả 4 bài). Dạng câu theo khung Công
     văn 7991: nhiều lựa chọn, đúng/sai, đúng/sai 4 ý về một tình huống, điền (tục ngữ), nối cột (ví dụ – loại truyền thống). Câu
     mới khác câu của các đề cuối kì I (cùng Bài 1–4). */
  "gdcd6-gk1-de2": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, nửa đầu học kì I: Bài 1 Tự hào về truyền thống gia đình, dòng họ; Bài 2 Yêu thương con người; Bài 3 Siêng năng, kiên trì; Bài 4 Tôn trọng sự thật. Có trường chỉ kiểm tra đến Bài 3, phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Truyền thống gia đình, dòng họ", type: "fill", q: "Hoàn thành câu tục ngữ nói về việc con cháu tiếp nối và phát huy truyền thống của cha ông: “Con hơn cha là nhà có ___.”", ans: ["phúc"], x: "“Con hơn cha là nhà có phúc”: con cháu giỏi giang, làm được nhiều điều tốt hơn cha ông là niềm vui, niềm tự hào của cả gia đình. Đó cũng là cách phát huy truyền thống gia đình, dòng họ.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Truyền thống của gia đình, dòng họ thường được lưu giữ qua đâu?", o: ["Gia phả, nhà thờ họ và những đồ vật xưa của gia đình", "Sổ tiết kiệm và tài sản riêng của từng người", "Những trò chơi điện tử được nhiều người chơi", "Những bộ quần áo mới mua trong năm"], x: "Gia phả ghi tên tuổi, công lao của các thế hệ trong dòng họ; nhà thờ họ và những đồ vật xưa của gia đình giúp con cháu biết về truyền thống của gia đình, dòng họ mình.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "tf", q: "Thờ cúng tổ tiên, ông bà thể hiện lòng biết ơn đối với những người đã sinh ra và nuôi dưỡng mình.", a: true, x: "Đúng. Thờ cúng tổ tiên, ông bà là nét đẹp lâu đời của các gia đình Việt Nam, thể hiện lòng biết ơn, sự kính trọng với các thế hệ đi trước.", lv: 1 },
      { topic: "Truyền thống gia đình, dòng họ", type: "match", q: "Nối mỗi ví dụ với loại truyền thống phù hợp.", l: ["Dòng họ có nhiều đời làm nghề đúc đồng", "Nhiều người trong họ từng tham gia bảo vệ Tổ quốc", "Con cháu luôn kính trọng, chăm sóc ông bà, cha mẹ"], r: ["Truyền thống nghề nghiệp", "Truyền thống yêu nước", "Truyền thống hiếu thảo", "Truyền thống thể thao"], x: "Nhiều đời cùng làm một nghề là truyền thống nghề nghiệp; tham gia bảo vệ Tổ quốc là truyền thống yêu nước; kính trọng, chăm sóc ông bà, cha mẹ là truyền thống hiếu thảo. Ô “Truyền thống thể thao” không ứng với ví dụ nào.", lv: 2 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Bạn N nói: «Nhà mình bình thường lắm, chẳng có truyền thống gì để tự hào.» Nhận xét nào về ý kiến của N là đúng?", o: ["Chưa đúng, vì nhà nào cũng có nét đẹp như cần cù, yêu thương nhau", "Đúng, vì chỉ những gia đình giàu có mới có truyền thống", "Đúng, vì truyền thống chỉ có ở những dòng họ nổi tiếng", "Chưa đúng, vì gia đình nào cũng có nhiều tài sản để lại"], x: "Truyền thống là những giá trị tốt đẹp được giữ gìn qua các thế hệ, không phụ thuộc vào giàu nghèo hay nổi tiếng. Gia đình bình thường vẫn có những nét đẹp đáng tự hào như cần cù lao động, sống trung thực, yêu thương nhau.", lv: 2 },
      { topic: "Truyền thống gia đình, dòng họ", type: "tf4", q: "Lớp 6A tổ chức buổi “Kể chuyện gia đình em”. Mỗi cách chuẩn bị sau của Minh đúng hay sai?", o: ["Bịa thêm vài chuyện cho gia đình mình nghe oai hơn.", "Chuẩn bị kể về nghề làm bánh truyền thống của bà nội, kèm vài tấm ảnh bà đang làm bánh.", "Chuẩn bị chê truyền thống nhà các bạn khác để nhà mình nổi bật hơn.", "Xin phép bố mẹ trước khi mang một bức ảnh xưa của gia đình đến lớp."], a: [false, true, false, true], x: "a) Sai: bịa chuyện là không trung thực, không phải tự hào đúng đắn. b), d) Đúng: kể về một truyền thống có thật của gia đình, có ảnh minh hoạ (mang ảnh đi thì xin phép bố mẹ) giúp Minh kể đúng, kể hay về truyền thống gia đình. c) Sai: tự hào về gia đình mình không có nghĩa là coi thường gia đình người khác.", lv: 3 },
      { topic: "Truyền thống gia đình, dòng họ", type: "mc", q: "Ông nội và bố của Hưng đều là thợ mộc giỏi. Hưng lại thích vẽ, mong sau này trở thành kiến trúc sư, nên băn khoăn không biết như vậy có phải là quay lưng với truyền thống gia đình không. Lời khuyên nào phù hợp nhất với Hưng?", o: ["Hưng có thể theo nghề mình thích mà vẫn giữ đức tính cần cù, khéo léo của gia đình", "Hưng bắt buộc phải làm thợ mộc như ông và bố thì mới là con cháu ngoan", "Hưng nên giấu bố mẹ chuyện mình thích vẽ để khỏi làm mọi người buồn", "Hưng nên coi nghề mộc là nghề cũ, không cần tìm hiểu hay trân trọng nữa"], x: "Giữ gìn truyền thống không có nghĩa là ai cũng phải làm đúng nghề của ông cha. Hưng vẫn có thể theo đuổi ước mơ, đồng thời trân trọng nghề mộc của gia đình và học những đức tính quý như cần cù, khéo léo, tỉ mỉ.", lv: 3 },
      { topic: "Yêu thương con người", type: "fill", q: "Hoàn thành câu tục ngữ: “Một miếng khi đói bằng một ___ khi no.”", ans: ["gói"], x: "Câu tục ngữ khuyên giúp đỡ người khác đúng lúc họ khó khăn: một chút giúp đỡ khi người ta đang thiếu thốn quý hơn rất nhiều so với cho thật nhiều khi người ta đã đủ đầy.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Người biết yêu thương con người thường có biểu hiện nào dưới đây?", o: ["Cảm thông, sẵn sàng giúp đỡ người gặp khó khăn", "Chỉ quan tâm đến việc của riêng mình", "Chỉ giúp người khác khi có người nhìn thấy", "Chỉ giúp người khác khi được trả công"], x: "Yêu thương con người thể hiện ở sự quan tâm, cảm thông, chia sẻ và sẵn sàng giúp đỡ người khác, nhất là người gặp khó khăn, mà không đòi được đền đáp hay được khen.", lv: 1 },
      { topic: "Yêu thương con người", type: "tf", q: "Tha thứ cho người đã biết nhận lỗi và sửa lỗi cũng là một biểu hiện của lòng yêu thương con người.", a: true, x: "Đúng. Yêu thương con người không chỉ là giúp đỡ, chia sẻ mà còn là biết cảm thông, tha thứ cho người khác khi họ đã nhận ra và sửa lỗi.", lv: 1 },
      { topic: "Yêu thương con người", type: "mc", q: "Việc làm nào dưới đây chưa thật sự xuất phát từ lòng yêu thương con người?", o: ["Quyên góp cho vùng lũ chỉ để chụp ảnh đăng lên mạng khoe", "Lặng lẽ góp sách vở cho bạn khó khăn trong lớp", "Hỏi thăm, động viên bạn có người thân bị ốm", "Nhường phần bánh cho em nhỏ đang đói"], x: "Yêu thương thật sự xuất phát từ tấm lòng, không nhằm khoe khoang. Quyên góp chỉ để chụp ảnh khoe thì mục đích là để được khen, chưa phải vì thương người gặp khó khăn.", lv: 2 },
      { topic: "Yêu thương con người", type: "tf", q: "Cho bạn chép bài trong giờ kiểm tra là cách thể hiện lòng yêu thương bạn.", a: false, x: "Sai. Cho chép bài là giúp bạn gian lận, không giúp bạn tiến bộ. Yêu thương bạn đúng cách là giảng lại bài, cùng bạn ôn tập để bạn tự làm được.", lv: 2 },
      { topic: "Yêu thương con người", type: "tf4", q: "Bố của bạn Tú lớp 6B bị ốm nặng, phải nằm viện lâu ngày; mấy hôm nay Tú rất buồn, ít nói. Mỗi việc làm sau của các bạn trong lớp đúng hay sai?", o: ["Rủ Tú cùng học nhóm, cùng chơi để Tú bớt buồn.", "Tò mò hỏi đi hỏi lại về bệnh của bố Tú ngay giữa lớp.", "Để Tú ngồi một mình vì nghĩ mình chẳng giúp được gì.", "Viết lời động viên, cùng cô chủ nhiệm đến thăm gia đình Tú."], a: [true, false, false, true], x: "a), d) Đúng: ở bên, động viên, thăm hỏi là cách chia sẻ nỗi buồn với bạn. b) Sai: hỏi tò mò giữa lớp làm bạn thêm buồn. c) Sai: thờ ơ, để bạn một mình là thiếu quan tâm; những việc nhỏ như ngồi cạnh, rủ bạn cùng học cũng giúp bạn bớt buồn.", lv: 3 },
      { topic: "Yêu thương con người", type: "mc", q: "Nhà bác Ba bên cạnh bị cháy bếp, may không ai bị thương nhưng đồ đạc hư hỏng nhiều. Gia đình Khôi nên làm gì?", o: ["Sang hỏi thăm, giúp dọn dẹp và cho mượn đồ dùng cần thiết", "Đóng cửa lại, coi như không biết chuyện gì xảy ra", "Đứng xem rồi đi kể chuyện khắp xóm cho mọi người cùng biết", "Chỉ sang giúp nếu bác Ba hứa sẽ trả công cho gia đình"], x: "Hàng xóm gặp hoạn nạn thì cần quan tâm, chia sẻ bằng việc làm cụ thể như hỏi thăm, giúp dọn dẹp, cho mượn đồ dùng. Thờ ơ, tò mò bàn tán hay đòi trả công đều trái với yêu thương con người.", lv: 3 },
      { topic: "Siêng năng, kiên trì", type: "fill", q: "Hoàn thành câu tục ngữ khuyên chăm chỉ, bền bỉ: “Kiến tha lâu cũng đầy ___.”", ans: ["tổ"], x: "Con kiến nhỏ, mỗi lần chỉ tha được một chút, nhưng tha mãi thì cũng đầy tổ: chăm chỉ, bền bỉ làm từng chút một thì sẽ đạt được kết quả lớn.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Câu tục ngữ, thành ngữ nào dưới đây chê thói lười biếng?", o: ["Há miệng chờ sung", "Có chí thì nên", "Năng nhặt chặt bị", "Ăn kĩ no lâu, cày sâu tốt lúa"], x: "“Há miệng chờ sung” chê người lười biếng, chỉ ngồi chờ sung rụng vào miệng mà không chịu làm. “Có chí thì nên” khuyên kiên trì; “Năng nhặt chặt bị” khuyên chăm chỉ góp nhặt; “Ăn kĩ no lâu, cày sâu tốt lúa” khuyên làm việc cẩn thận, chăm chỉ.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Việc làm nào dưới đây thể hiện tính kiên trì?", o: ["Tập mãi một động tác võ cho đến khi làm được", "Thấy việc khó thì để đó, khi nào có hứng mới làm", "Làm cùng lúc nhiều việc nhưng việc nào cũng bỏ dở", "Chỉ chọn những việc dễ để làm cho nhanh xong"], x: "Kiên trì là quyết tâm làm đến cùng, không nản dù gặp khó khăn. Tập mãi một động tác cho đến khi làm được là kiên trì; để dở việc khó, bỏ dở giữa chừng hay chỉ chọn việc dễ đều chưa phải là kiên trì.", lv: 1 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Bạn Hòa gặp bài toán khó nào cũng cố làm đến cùng mới thôi, nhưng chỉ học vào hôm nào thấy thích, còn lại thì để bài vở dồn đống. Nhận xét nào đúng về Hòa?", o: ["Hòa kiên trì nhưng chưa siêng năng", "Hòa vừa siêng năng vừa kiên trì", "Hòa lười biếng, không chịu học", "Hòa siêng năng nhưng chưa kiên trì"], x: "Hòa cố làm bài khó đến cùng: Hòa kiên trì. Nhưng Hòa chỉ học khi thích, để bài vở dồn lại, không thường xuyên, đều đặn: Hòa chưa siêng năng. Siêng năng và kiên trì thường đi cùng nhau, cần rèn luyện cả hai.", lv: 2 },
      { topic: "Siêng năng, kiên trì", type: "tf", q: "Làm việc gì cũng cố làm thật nhanh cho xong, không quan tâm đến kết quả, là biểu hiện của siêng năng.", a: false, x: "Sai. Siêng năng là cần cù, tự giác, miệt mài làm việc thường xuyên, đều đặn và có trách nhiệm với kết quả công việc. Làm qua loa cho xong là đối phó, không phải siêng năng.", lv: 2 },
      { topic: "Siêng năng, kiên trì", type: "tf4", q: "Vinh được giao chăm sóc bồn hoa của lớp, nhưng mới được mấy hôm đã chán vì cây chưa ra hoa. Mỗi lời khuyên sau dành cho Vinh đúng hay sai?", o: ["Bỏ bồn hoa, xin cô đổi sang một việc khác dễ hơn.", "Cây cần thời gian mới ra hoa; cứ tưới nước, nhổ cỏ hằng ngày rồi sẽ thấy kết quả.", "Mỗi tuần ghi lại cây cao thêm bao nhiêu để thấy cây đang lớn.", "Tưới thật nhiều nước một lần cho cây lớn nhanh rồi thôi."], a: [false, true, true, false], x: "a) Sai: bỏ việc được giao khi chưa thấy kết quả là thiếu kiên trì. b), c) Đúng: chăm cây cần bền bỉ ngày qua ngày; thấy cây lớn dần giúp Vinh thêm vui, không nản. d) Sai: tưới dồn một lần không giúp cây lớn nhanh mà còn làm hỏng cây; việc gì cũng cần làm đều đặn.", lv: 3 },
      { topic: "Siêng năng, kiên trì", type: "mc", q: "Nhóm của Lan được giao làm mô hình ngôi nhà bằng bìa. Làm đến lần thứ hai, mô hình vẫn bị đổ, các bạn trong nhóm muốn bỏ cuộc. Là nhóm trưởng, Lan nên nói gì?", o: ["Mình cùng tìm xem vì sao mô hình bị đổ rồi sửa và làm lại nhé!", "Thôi, bỏ đi các bạn ạ, nhóm khác làm đẹp hơn mình rồi.", "Ai làm đổ mô hình thì người đó tự làm lại một mình.", "Mình mua luôn một mô hình làm sẵn để nộp cho nhanh."], x: "Gặp thất bại, người kiên trì tìm nguyên nhân để sửa và tiếp tục làm. Lan động viên cả nhóm cùng tìm lỗi, làm lại là cách giữ tinh thần kiên trì. Bỏ cuộc, đổ lỗi hay mua sẵn đều không giúp nhóm tiến bộ.", lv: 3 },
      { topic: "Tôn trọng sự thật", type: "fill", q: "Hoàn thành câu tục ngữ: “Mất lòng trước, được lòng ___.”", ans: ["sau"], x: "Nói thật có thể làm người khác phật lòng lúc đầu, nhưng về sau họ sẽ hiểu và quý trọng mình. Câu tục ngữ khuyên ta dám nói đúng sự thật.", lv: 1 },
      { topic: "Tôn trọng sự thật", type: "tf4", q: "Trong giờ thực hành, Linh được giao đo và ghi lại nhiệt độ của một cốc nước. Mỗi nhận xét sau về việc làm của Linh đúng hay sai?", o: ["Linh sửa số đo cho giống kết quả của nhóm bên cạnh: Linh tôn trọng sự thật.", "Linh chép kết quả của bạn năm trước cho nhanh: Linh tôn trọng sự thật.", "Linh ghi đúng số đo được, dù số đó khác với số của nhóm bạn: Linh tôn trọng sự thật.", "Thấy mình đọc nhiệt kế sai, Linh báo với thầy để đo lại: Linh tôn trọng sự thật."], a: [false, false, true, true], x: "a), b) Sai: sửa số liệu, chép kết quả của người khác là làm sai lệch sự thật. c), d) Đúng: ghi đúng điều mình đo được, dám nhận mình đo sai để đo lại là tôn trọng sự thật.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Cả lớp nghĩ bạn Nam làm vỡ cửa kính, nhưng Minh biết rõ người làm vỡ là một bạn khác. Minh đứng ra kể lại đúng sự việc với cô giáo. Việc làm của Minh cho thấy điều gì?", o: ["Minh dám nói đúng điều mình biết để bạn không bị oan", "Minh thích mách lẻo chuyện của các bạn trong lớp", "Minh muốn được cô giáo chú ý và khen ngợi mình", "Minh muốn gây chuyện với bạn đã làm vỡ cửa kính"], x: "Minh nói đúng điều mình đã thấy để bạn Nam không bị nghi oan. Đó là biểu hiện của tôn trọng sự thật: dám nói thật, bảo vệ lẽ phải, không để người khác chịu oan.", lv: 2 },
      { topic: "Tôn trọng sự thật", type: "mc", q: "Khang lỡ tay làm hỏng chiếc máy tính cầm tay của bạn cùng bàn khi bạn ra ngoài. Khang nên làm gì?", o: ["Xin lỗi bạn, kể rõ chuyện đã xảy ra và tìm cách sửa hoặc đền", "Lặng lẽ để máy lại chỗ cũ, coi như mình không biết gì", "Nói với bạn là máy tính tự nhiên bị hỏng, không phải do mình", "Bảo rằng bạn ngồi bàn sau đã nghịch làm hỏng máy tính"], x: "Dám nhận lỗi, kể đúng sự việc và chịu trách nhiệm về việc mình làm là tôn trọng sự thật. Im lặng, nói dối hay đổ lỗi cho người khác đều là che giấu sự thật.", lv: 3 }
    ]
  },

  /* ---------- GDCD 6 · Kiểm tra giữa học kì II (Kết nối tri thức) ----------
     Phạm vi nửa đầu học kì II, ghi ở note: Bài 7 Ứng phó với tình huống nguy hiểm, Bài 8 Tiết kiệm, Bài 9 Công dân nước Cộng hòa
     xã hội chủ nghĩa Việt Nam. Câu tự soạn (Phiên N12). Hai đề là kho của đề ngẫu nhiên "gdcd6-gk2-ngau-nhien" (không có câu riêng
     nên không ghi vào file này; ma trận ở data/banks/index.js); hai đề cùng phân bố chủ đề và mức như ma trận, nên ô nào cũng có
     gấp đôi số câu ô đó rút. Cách xếp mức như đề cuối kì I ở đầu file: phân loại tình huống nguy hiểm, nhận xét việc làm, ý kiến
     của một bạn là Hiểu; nên làm gì trước một tình huống, sắp xếp các việc cần làm là Vận dụng. Câu ở hai ô khác nhau, cả hai câu
     của một ô rút từ 2 câu trở lên, có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời giải không ghi sẵn đáp án của
     câu khác. Mỗi tình huống chỉ có ở một câu; hai câu cùng một loại nguy hiểm (cháy, lũ, đuối nước, người lạ) hỏi hai việc
     khác nhau, ví dụ đuối nước: phòng tránh và cứu người ngã xuống nước khi mình không biết bơi. Câu về quốc tịch đúng với Luật
     Quốc tịch Việt Nam sửa đổi năm 2025 (Luật số 79/2025/QH15), cũng đúng với bản năm 2008 sách trích: không ghi chi tiết đã
     đổi như "thỏa thuận bằng văn bản". */
  "gdcd6-gk2-de1": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, nửa đầu học kì II: Bài 7 Ứng phó với tình huống nguy hiểm; Bài 8 Tiết kiệm; Bài 9 Công dân nước Cộng hòa xã hội chủ nghĩa Việt Nam. Có trường chỉ kiểm tra đến Bài 8, phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Sự việc nào dưới đây là một tình huống nguy hiểm?", o: ["Đang đi trên đường thì một cành cây to bên đường bị gió mạnh làm gãy, rơi xuống", "Bài kiểm tra Toán có một câu khó", "Cả lớp chơi kéo co trong giờ ra chơi", "Trời nắng đẹp, cả nhà đi dạo công viên"], x: "Cành cây gãy rơi xuống bất ngờ có thể làm người đi đường bị thương: đó là tình huống nguy hiểm. Câu toán khó, trò chơi kéo co, đi dạo công viên không đe dọa sức khỏe, tính mạng hay tài sản. Tình huống nguy hiểm có thể đến từ tự nhiên hoặc từ con người.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "match", q: "Nối mỗi tình huống với số điện thoại khẩn cấp cần gọi.", l: ["Phát hiện đám cháy lớn ở nhà kho gần nhà", "Có người bị ngất, cần xe cứu thương", "Thấy kẻ gian đang cạy khóa nhà hàng xóm", "Biết một bạn nhỏ thường xuyên bị đánh đập, bạo hành"], r: ["114", "115", "113", "111"], x: "114: báo cháy, cứu nạn, cứu hộ; 115: cấp cứu y tế; 113: công an, khi có kẻ gian, trộm cướp, gây rối; 111: Tổng đài quốc gia bảo vệ trẻ em. Gọi các số này không mất tiền.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "tf", q: "Khi có mưa dông, sấm sét, đứng trú dưới gốc cây to giữa cánh đồng là an toàn.", a: false, x: "Sai. Cây cao giữa cánh đồng dễ bị sét đánh. Khi có sấm sét, cần vào trú trong nhà kiên cố, tránh xa cây cao, cột điện, không đứng giữa nơi trống trải.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "fill", q: "Đang ngồi học trong lớp thì mặt đất rung lắc mạnh vì động đất. Em nhanh chóng chui xuống gầm ___ và dùng tay hoặc cặp sách che đầu, cổ.", ans: ["bàn"], x: "Gầm bàn chắc chắn giúp che chắn cơ thể khỏi đồ vật rơi xuống. Cần tránh xa cửa kính, tủ cao; khi hết rung lắc mới theo hướng dẫn của thầy cô ra nơi trống trải.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Tình huống nào dưới đây là tình huống nguy hiểm từ tự nhiên?", o: ["Lũ quét, sạt lở đất sau những trận mưa lớn", "Bị bỏng vì nghịch pháo nổ", "Bị ngộ độc vì ăn thức ăn ôi thiu", "Bị điện giật khi sửa ổ điện mà chưa ngắt cầu dao"], x: "Lũ quét, sạt lở đất do mưa lớn là hiện tượng tự nhiên gây nguy hiểm. Ba tình huống còn lại do hành động của con người gây ra.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "tf4", q: "Mỗi tình huống sau là tình huống nguy hiểm từ con người đúng hay sai?", o: ["Bị người lạ dụ dỗ đi theo để được cho quà.", "Bị sét đánh khi trời mưa dông.", "Cháy nhà vì để bếp than đang cháy gần đống củi khô.", "Bị ngã gãy tay vì trèo lên cây cao hái quả."], a: [true, false, true, true], x: "a), c), d) Đúng: đó là những nguy hiểm do hành vi cố ý hoặc vô ý của con người gây ra. b) Sai: sét đánh là tình huống nguy hiểm từ tự nhiên.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Bạn K cho rằng: “Tình huống nguy hiểm chỉ xảy ra với người lớn, trẻ em không cần học cách ứng phó.” Nhận xét nào về ý kiến của K là đúng?", o: ["Chưa đúng, vì trẻ em cũng có thể gặp nguy hiểm, cần biết cách tự bảo vệ mình", "Đúng, vì trẻ em luôn có người lớn ở bên bảo vệ", "Đúng, vì tình huống nguy hiểm rất hiếm khi xảy ra", "Chưa đúng, vì chỉ trẻ em mới gặp tình huống nguy hiểm"], x: "Ai cũng có thể gặp tình huống nguy hiểm, kể cả trẻ em. Biết cách ứng phó giúp các em bảo vệ bản thân và giúp đỡ người khác khi cần.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "tf4", q: "Hoa đang ở nhà một mình thì có người lạ gõ cửa, xưng là nhân viên điện lực đến kiểm tra công tơ điện. Mỗi cách xử lí sau của Hoa đúng hay sai?", o: ["Không mở cửa, đề nghị người đó quay lại khi bố mẹ có nhà.", "Mở cửa ngay vì người đó mặc đồng phục.", "Gọi điện cho bố mẹ để hỏi ý kiến.", "Nói cho người lạ biết mình đang ở nhà một mình."], a: [true, false, true, false], x: "a), c) Đúng: không mở cửa cho người lạ và hỏi ý kiến bố mẹ giúp Hoa an toàn. b) Sai: kẻ xấu có thể mặc đồng phục giả để lừa. d) Sai: cho người lạ biết mình ở nhà một mình có thể bị kẻ xấu lợi dụng.", lv: 3 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "order", q: "Nhà Tú ở vùng trũng, mùa mưa hay bị ngập lụt. Sắp xếp các việc gia đình Tú nên làm theo thứ tự, từ khi có tin lũ đến khi lũ qua.", o: ["Nghe đài, xem ti vi để nắm tin lũ sắp về", "Chuẩn bị nước uống, đồ ăn khô, đèn pin, áo phao", "Di chuyển đến nơi cao ráo, an toàn theo hướng dẫn của chính quyền", "Chỉ trở về nhà khi chính quyền thông báo đã an toàn"], x: "Trước hết phải nắm tin lũ, rồi chuẩn bị đồ dùng thiết yếu, sau đó di chuyển đến nơi an toàn theo hướng dẫn. Khi lũ qua, chỉ trở về nhà lúc chính quyền thông báo đã an toàn.", lv: 3 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Trên đường đi học về, Minh thấy một em nhỏ trượt chân ngã xuống mương nước sâu, đang chới với. Minh không biết bơi. Minh nên làm gì?", o: ["Hô to gọi người lớn đến giúp, tìm cây sào hoặc sợi dây đưa cho em nhỏ bám vào", "Nhảy ngay xuống mương để kéo em nhỏ lên", "Chạy về nhà, không kể với ai", "Đứng quay video để đăng lên mạng"], x: "Không biết bơi mà nhảy xuống cứu thì cả hai đều gặp nguy hiểm. Minh cần hô to gọi người lớn, đứng trên bờ đưa sào, dây hoặc vật nổi cho em nhỏ bám vào.", lv: 3 },
      { topic: "Tiết kiệm", type: "mc", q: "Bạn nào dưới đây đã biết tiết kiệm?", o: ["Giang mua vở vừa đủ dùng cho cả năm học và giữ gìn cẩn thận để không phải mua thêm", "Thắng mua thật nhiều bút vì cửa hàng đang giảm giá, dùng không hết", "Hạnh đi chợ cùng mẹ, đòi mua món đồ chơi giống hệt món đã có ở nhà", "Lộc tiêu hết tiền tiêu vặt ngay trong ngày được cho"], x: "Giang chỉ mua đồ cần dùng và giữ gìn để dùng được lâu: đó là tiết kiệm. Mua thừa vì rẻ, đòi mua đồ đã có, tiêu hết tiền ngay đều là chưa biết tiết kiệm. Tiết kiệm là dùng hợp lí cả tiền bạc, đồ dùng, thời gian và sức lực.", lv: 1 },
      { topic: "Tiết kiệm", type: "fill", q: "Hoàn thành câu thành ngữ nói về tiết kiệm: “Tích ___ thành đại.”", ans: ["tiểu"], x: "“Tích tiểu thành đại”: góp nhặt nhiều cái nhỏ sẽ thành cái lớn.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Biểu hiện nào dưới đây là biết tiết kiệm sức lực?", o: ["Làm việc có kế hoạch, xen kẽ làm việc với nghỉ ngơi", "Thức khuya chơi điện tử rồi ngủ gật trong lớp", "Làm liền một mạch cả ngày đến kiệt sức", "Cố khiêng một mình chiếc tủ nặng dù có thể nhờ bạn cùng khiêng"], x: "Làm việc có kế hoạch, biết nghỉ ngơi đúng lúc giúp giữ sức khỏe, làm việc bền bỉ. Thức khuya, làm quá sức hay cố làm một mình việc quá nặng đều làm hao phí sức lực.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Tiết kiệm có ý nghĩa gì đối với mỗi người?", o: ["Có khoản để dành, không lúng túng khi gia đình gặp việc cần tiêu bất ngờ", "Giúp không bao giờ phải làm việc vất vả", "Giúp được mọi người tặng quà nhiều hơn", "Giúp không cần học tập mà vẫn thành công"], x: "Sống tiết kiệm giúp mỗi người có của để dành, chủ động khi gặp việc cần tiêu bất ngờ như ốm đau, sửa nhà.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "An dùng tiền tiêu vặt để mua sách cần cho việc học, phần còn lại bỏ lợn đất. Bình có tiền nhưng không chịu mua cả quyển vở còn thiếu, đành học thiếu vở. Nhận xét nào đúng?", o: ["An biết tiết kiệm; Bình keo kiệt, bủn xỉn", "An keo kiệt, bủn xỉn; Bình biết tiết kiệm", "Cả hai bạn đều biết tiết kiệm", "Cả hai bạn đều lãng phí"], x: "An chi tiêu đúng việc cần thiết và để dành phần còn lại: An biết tiết kiệm. Bình không dám chi cả cho việc cần thiết là keo kiệt, bủn xỉn. Tiết kiệm khác với keo kiệt.", lv: 2 },
      { topic: "Tiết kiệm", type: "mc", q: "Hùng nói: “Nhà mình có điều kiện nên không cần tiết kiệm.” Nhận xét nào về ý kiến của Hùng là đúng?", o: ["Chưa đúng, vì của cải do công sức lao động làm ra, ai cũng cần biết quý trọng, không dùng phung phí", "Đúng, vì chỉ nhà nghèo mới cần tiết kiệm", "Đúng, vì nhà có điều kiện thì không bao giờ hết tiền", "Chưa đúng, vì nhà có điều kiện phải tiêu nhiều hơn mới đúng"], x: "Dù giàu hay nghèo, ai cũng cần tiết kiệm. Của cải do công sức lao động làm ra; dùng phung phí thì của nhiều mấy cũng hết, lại làm hao phí tài nguyên của xã hội.", lv: 2 },
      { topic: "Tiết kiệm", type: "match", q: "Nối mỗi việc làm với điều mà việc làm đó giúp tiết kiệm.", l: ["Dùng hết trang vở cũ rồi mới dùng vở mới", "Sửa lại chiếc ghế bị lung lay thay vì vứt đi", "Đi bộ đến trường gần nhà thay vì nhờ bố mẹ chở bằng xe máy"], r: ["Đồ dùng học tập", "Đồ đạc trong nhà", "Xăng xe và tiền bạc"], x: "Dùng hết vở cũ là tiết kiệm đồ dùng học tập; sửa ghế là tiết kiệm đồ đạc trong nhà; đi bộ khi trường gần giúp tiết kiệm xăng xe, tiền bạc và còn tốt cho sức khỏe.", lv: 2 },
      { topic: "Tiết kiệm", type: "mc", q: "Q thường mua bút mới, dùng vài hôm thấy chán lại vứt đi dù bút vẫn viết tốt. Nhận xét nào đúng về Q?", o: ["Q chưa biết tiết kiệm, gây lãng phí tiền bạc và đồ dùng", "Q biết tiết kiệm vì lúc nào cũng có bút mới để dùng", "Q là người cẩn thận, biết giữ gìn đồ dùng", "Việc làm của Q không ảnh hưởng gì đến ai"], x: "Vứt bỏ đồ dùng còn tốt để mua cái mới là lãng phí tiền bạc của gia đình. Q nên giữ gìn bút cẩn thận, chỉ mua khi thật sự cần.", lv: 2 },
      { topic: "Tiết kiệm", type: "mc", q: "Tết vừa rồi, Nam được mừng tuổi 500 000 đồng. Cách dùng tiền nào thể hiện Nam biết tiết kiệm?", o: ["Gửi bố mẹ giữ phần lớn, dùng một ít mua sách, đồ dùng học tập cần thiết", "Tiêu hết vào chơi điện tử trong một tuần", "Mua thật nhiều đồ chơi giống các bạn", "Cho các bạn mượn hết để được khen là hào phóng"], x: "Dùng tiền vào việc cần thiết và để dành phần lớn là biết tiết kiệm. Tiêu hết vào trò chơi, mua đồ chơi theo bạn hay cho mượn hết đều chưa biết quý đồng tiền.", lv: 3 },
      { topic: "Tiết kiệm", type: "tf4", q: "Lớp 6B ăn bán trú, mỗi ngày còn thừa nhiều cơm, canh phải đổ đi. Mỗi đề xuất sau của các bạn đúng hay sai?", o: ["Lấy vừa đủ suất ăn, ăn hết phần của mình.", "Đổ bỏ những món không thích cho nhanh.", "Nhắc nhau không lấy thừa, không bỏ phí thức ăn.", "Lấy thật nhiều cho chắc, ăn không hết thì để lại."], a: [true, false, true, false], x: "a), c) Đúng: lấy vừa đủ và ăn hết phần của mình là tiết kiệm. b), d) Sai: đổ bỏ hay lấy thừa thức ăn là lãng phí.", lv: 3 },
      { topic: "Tiết kiệm", type: "order", q: "Mai muốn tự để dành tiền mua một hộp màu vẽ. Sắp xếp các bước Mai nên làm theo thứ tự hợp lí.", o: ["Hỏi giá hộp màu để biết cần có bao nhiêu tiền", "Tính xem mỗi tuần cần để dành bao nhiêu tiền và sau mấy tuần thì đủ", "Mỗi tuần bớt các khoản chi không cần thiết để bỏ đủ số tiền đã tính vào lợn đất", "Khi đã đủ tiền, cùng bố mẹ đi mua hộp màu"], x: "Phải biết hộp màu giá bao nhiêu thì mới tính được mỗi tuần cần để dành bao nhiêu, sau mấy tuần thì đủ. Biết số tiền đó rồi, mỗi tuần Mai bớt các khoản chi không cần thiết để bỏ đủ số tiền đã tính vào lợn đất; khi đủ tiền mới đi mua.", lv: 3 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Anh Sơn là công dân Việt Nam. Điều nào sau đây đúng với anh Sơn?", o: ["Anh Sơn có các quyền và nghĩa vụ do pháp luật Việt Nam quy định", "Anh Sơn chỉ có quyền, không phải thực hiện nghĩa vụ nào", "Anh Sơn chỉ có nghĩa vụ, không có quyền gì", "Quyền và nghĩa vụ của anh Sơn do dòng họ của anh đặt ra"], x: "Là công dân Việt Nam, anh Sơn được hưởng các quyền và phải thực hiện các nghĩa vụ mà pháp luật Việt Nam quy định; quyền đi đôi với nghĩa vụ. Trẻ em cũng là công dân.", lv: 1 },
      { topic: "Công dân nước Việt Nam", type: "tf", q: "Công dân Việt Nam đang học tập, làm việc ở nước ngoài vẫn là công dân Việt Nam.", a: true, x: "Đúng. Đi học tập, làm việc ở nước ngoài một thời gian không làm thay đổi việc người đó là công dân Việt Nam.", lv: 1 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Mẹ của Tom là công dân Việt Nam, bố là người Úc. Tom sinh ra ở Úc. Khi làm thủ tục khai sinh cho Tom, bố mẹ đã thỏa thuận chọn quốc tịch Việt Nam cho con. Theo Luật Quốc tịch Việt Nam, nhận xét nào đúng?", o: ["Tom có quốc tịch Việt Nam", "Tom không thể có quốc tịch Việt Nam vì sinh ra ở nước ngoài", "Tom không thể có quốc tịch Việt Nam vì bố là người nước ngoài", "Tom chỉ được có quốc tịch Việt Nam khi đủ 18 tuổi"], x: "Trẻ em có cha hoặc mẹ là công dân Việt Nam, người kia là công dân nước ngoài, thì có quốc tịch Việt Nam nếu cha mẹ thỏa thuận chọn quốc tịch Việt Nam cho con khi làm thủ tục khai sinh.", lv: 2 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Lớp 6A tổ chức tuần lễ “Tự hào là công dân Việt Nam”. Việc làm nào của học sinh là phù hợp nhất?", o: ["Tìm hiểu, giới thiệu những tấm gương người Việt Nam làm rạng danh đất nước và chăm chỉ học tập, rèn luyện", "Chê bai các nước khác để thấy nước mình hơn", "Chỉ hát thật to bài quốc ca mà không cần cố gắng học tập", "Không tham gia vì việc đó chỉ dành cho người lớn"], x: "Tự hào là công dân Việt Nam thể hiện qua việc tìm hiểu về đất nước, học tập những tấm gương tốt và cố gắng học tập, rèn luyện để góp phần xây dựng đất nước; không phải bằng cách chê bai người khác.", lv: 3 }
    ]
  },

  "gdcd6-gk2-de2": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, nửa đầu học kì II: Bài 7 Ứng phó với tình huống nguy hiểm; Bài 8 Tiết kiệm; Bài 9 Công dân nước Cộng hòa xã hội chủ nghĩa Việt Nam. Có trường chỉ kiểm tra đến Bài 8, phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Việc làm nào dưới đây giúp học sinh phòng tránh đuối nước?", o: ["Học bơi, không tắm ở sông, suối, ao hồ khi không có người lớn đi cùng", "Rủ bạn ra sông tắm vào buổi trưa vắng người", "Chơi đùa sát mép ao, hồ sâu", "Bơi ra xa bờ ở khu vực có biển cấm bơi"], x: "Biết bơi và chỉ tắm ở nơi an toàn, có người lớn trông coi giúp phòng tránh đuối nước. Tắm sông một mình, chơi sát mép ao hồ, bơi ở nơi có biển cấm đều rất nguy hiểm.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "tf", q: "Khi nước lũ đang chảy xiết qua mặt đường, có thể lội qua nếu nước chỉ ngập đến đầu gối.", a: false, x: "Sai. Nước lũ chảy xiết có thể cuốn trôi người dù chỉ ngập thấp; dưới nước còn có thể có hố sâu, vật sắc nhọn. Tuyệt đối không lội qua chỗ nước chảy xiết.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Khi ngửi thấy mùi khí gas rò rỉ trong bếp, việc KHÔNG được làm là:", o: ["Bật công tắc đèn, quạt để xem cho rõ", "Khóa van bình gas nếu làm được", "Mở cửa cho thoáng khí", "Ra khỏi bếp và báo ngay cho người lớn"], x: "Bật công tắc điện có thể tạo tia lửa làm khí gas bốc cháy, phát nổ. Cần khóa van gas, mở cửa cho thoáng, ra khỏi bếp và báo người lớn.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Khi phải thoát ra khỏi đám cháy có nhiều khói, cần làm gì?", o: ["Dùng khăn ướt che mũi, miệng, cúi thấp người đi theo lối thoát hiểm", "Đứng thẳng người, chạy thật nhanh qua đám khói", "Vào thang máy để xuống tầng dưới cho nhanh", "Trốn vào tủ quần áo chờ đám cháy tắt"], x: "Khói nóng và độc bốc lên cao, nên cần cúi thấp người, dùng khăn ướt che mũi, miệng để hạn chế hít khói và đi theo lối thoát hiểm. Không dùng thang máy vì có thể bị mất điện, mắc kẹt; không trốn trong nhà.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Tình huống nào dưới đây là tình huống nguy hiểm từ con người?", o: ["Tai nạn giao thông do đi xe đạp dàn hàng ba, lạng lách trên đường", "Động đất làm nhà cửa rung lắc", "Mưa đá làm vỡ mái nhà", "Lốc xoáy làm tốc mái, đổ cây"], x: "Đi xe đạp dàn hàng ba, lạng lách là hành vi của con người gây ra tai nạn. Động đất, mưa đá, lốc xoáy là những tình huống nguy hiểm từ tự nhiên.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "tf4", q: "Mỗi ý sau về việc phòng tránh nguy hiểm khi có bão đúng hay sai?", o: ["Theo dõi bản tin dự báo thời tiết để biết đường đi của bão.", "Ra bờ biển, bờ sông xem sóng lớn khi bão đổ bộ.", "Chằng chống nhà cửa, cắt tỉa cành cây gần nhà trước khi bão đến.", "Khi bão đang đổ bộ, chạy ra ngoài nhặt đồ đạc bị gió thổi bay."], a: [true, false, true, false], x: "a), c) Đúng: nắm tin bão và chuẩn bị trước giúp giảm thiệt hại. b), d) Sai: ra ngoài khi bão đang đổ bộ rất dễ bị sóng cuốn, cây đổ, vật bay trúng người.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Thu cho rằng: “Chỉ cần tránh xa sông, hồ là sẽ không bao giờ gặp tình huống nguy hiểm.” Nhận xét nào về ý kiến của Thu là đúng?", o: ["Chưa đúng, vì tình huống nguy hiểm có thể xảy ra ở nhiều nơi như ở nhà, ở trường, trên đường", "Đúng, vì mọi tình huống nguy hiểm đều xảy ra ở sông, hồ", "Đúng, vì ở nhà thì không bao giờ có nguy hiểm", "Chưa đúng, vì chỉ trên đường mới có nguy hiểm"], x: "Tình huống nguy hiểm có thể xảy ra ở bất cứ đâu, ở nhà, ở trường hay trên đường. Vì vậy cần luôn cẩn thận và biết cách ứng phó.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "tf4", q: "Lan đang đứng chờ xe buýt về nhà thì một người lạ đến bắt chuyện, hỏi Lan học trường nào, nhà ở đâu rồi rủ Lan lên ô tô để chở về cho nhanh. Mỗi cách xử lí sau của Lan đúng hay sai?", o: ["Không nói tên trường, địa chỉ nhà cho người lạ.", "Đứng gần chỗ đông người, nhờ người lớn ở bến xe giúp nếu người đó cứ bám theo.", "Lên xe vì đi ô tô nhanh và mát hơn chờ xe buýt.", "Về nhà kể lại sự việc cho bố mẹ biết."], a: [true, true, false, true], x: "a), b), d) Đúng: không cho người lạ biết thông tin của mình, ở gần chỗ có người lớn và kể lại cho bố mẹ giúp Lan an toàn. c) Sai: không lên xe của người lạ, dù được rủ đi nhờ cho nhanh.", lv: 3 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Khoa đang chơi ở sân thì thấy một sợi dây điện bị đứt, rơi xuống vũng nước ngay lối đi. Khoa nên làm gì?", o: ["Tránh xa chỗ đó, nhắc các bạn không lại gần và báo cho thầy cô hoặc bác bảo vệ", "Lấy tay nhặt sợi dây điện vứt sang bên", "Dùng chân đá sợi dây ra khỏi vũng nước", "Lội qua vũng nước để xem dây còn điện không"], x: "Dây điện đứt rơi xuống nước có thể làm người đến gần bị điện giật. Khoa cần tránh xa, nhắc các bạn và báo cho thầy cô hoặc bác bảo vệ để cắt điện, xử lí.", lv: 3 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "order", q: "Trên đường đi học, Phong bị mấy bạn lớp trên chặn lại, đe dọa đòi tiền. Sắp xếp các việc Phong nên làm theo thứ tự hợp lí.", o: ["Không cãi nhau, tìm cách rời khỏi chỗ đó", "Đến ngay chỗ có thầy cô, bảo vệ hoặc người lớn", "Kể lại đầy đủ sự việc để thầy cô, bố mẹ cùng giải quyết"], x: "Trước hết Phong cần rời khỏi chỗ nguy hiểm, không cãi nhau để tránh bị đánh; rồi tìm đến người lớn để được bảo vệ; sau đó kể lại đầy đủ sự việc để thầy cô, bố mẹ cùng giải quyết, ngăn việc đó lặp lại.", lv: 3 },
      { topic: "Tiết kiệm", type: "mc", q: "Câu tục ngữ nào dưới đây khuyên chúng ta tiết kiệm?", o: ["Ăn phải dành, có phải kiệm", "Ăn quả nhớ kẻ trồng cây", "Thương người như thể thương thân", "Uống nước nhớ nguồn"], x: "“Ăn phải dành, có phải kiệm”: khi có ăn phải biết để dành, khi có của phải biết tiết kiệm. Ba câu còn lại nói về lòng biết ơn và yêu thương con người.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Biểu hiện nào dưới đây là tiết kiệm thời gian?", o: ["Soạn sẵn sách vở, quần áo từ tối hôm trước để sáng không mất công tìm", "Ngồi xem điện thoại hàng giờ liền", "Vừa học vừa xem ti vi nên làm bài rất lâu", "Ngủ dậy muộn rồi vội vàng đi học"], x: "Chuẩn bị sẵn từ tối giúp buổi sáng không mất thời gian tìm đồ. Xem điện thoại quá lâu, vừa học vừa xem ti vi, dậy muộn đều làm phí thời gian.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Câu thành ngữ nào dưới đây chê người tiêu xài quá tay, không biết tính toán?", o: ["Vung tay quá trán", "Năng nhặt chặt bị", "Góp gió thành bão", "Kiến tha lâu cũng đầy tổ"], x: "“Vung tay quá trán” chê người tiêu tiền quá mức, quá khả năng của mình. Ba câu còn lại khuyên chăm chỉ góp nhặt từng chút một.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Việc làm nào dưới đây thể hiện biết tiết kiệm, giữ gìn tài sản chung?", o: ["Giữ gìn sách mượn của thư viện để các bạn sau còn dùng được", "Viết, vẽ bậy lên tường lớp học", "Mang phấn của lớp về nhà chơi", "Xé giấy trong sổ đầu bài để gấp máy bay"], x: "Giữ gìn sách thư viện, đồ dùng của lớp là biết tiết kiệm của chung, giúp nhiều bạn khác cùng được dùng lâu dài. Viết vẽ bậy, mang đồ của lớp về nhà, xé giấy bừa bãi đều làm hỏng, hao phí tài sản chung.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Bà ngoại của Thảo thường giữ lại túi ni lông, hộp nhựa đã dùng để dùng lại nhiều lần. Nhận xét nào đúng về việc làm của bà?", o: ["Bà biết tiết kiệm, tận dụng đồ dùng và góp phần giảm rác thải", "Bà keo kiệt, bủn xỉn chứ không phải tiết kiệm", "Bà làm việc không cần thiết, mất thời gian", "Bà làm vậy chỉ vì không có tiền mua đồ mới"], x: "Dùng lại túi, hộp còn tốt là tận dụng đồ dùng, vừa đỡ tốn tiền vừa giảm rác thải ra môi trường. Đó là tiết kiệm, không phải keo kiệt.", lv: 2 },
      { topic: "Tiết kiệm", type: "tf4", q: "Mỗi việc làm sau là tiết kiệm nước đúng hay sai?", o: ["Tưới cây vào sáng sớm hoặc chiều mát để nước ít bay hơi.", "Dùng nước vo gạo để tưới cây.", "Để vòi nước chảy tràn chậu rồi mới khóa.", "Hứng nước mưa để lau nhà, tưới rau."], a: [true, true, false, true], x: "a), b), d) Đúng: tưới cây lúc trời mát, tận dụng nước vo gạo, nước mưa giúp tiết kiệm nước. c) Sai: để nước chảy tràn là lãng phí.", lv: 2 },
      { topic: "Tiết kiệm", type: "mc", q: "Việc làm nào dưới đây KHÔNG thể hiện tiết kiệm?", o: ["Tối nào cũng xin tiền mua đồ ăn vặt dù vừa ăn cơm no", "Mua vở loại vừa túi tiền mà vẫn tốt", "Xin lại sách cũ của anh chị để học", "Sửa lại chiếc xe đạp hỏng nhẹ thay vì mua xe mới"], x: "Mua đồ ăn vặt khi không đói là tiêu tiền không cần thiết. Ba việc còn lại đều là biết tiết kiệm.", lv: 2 },
      { topic: "Tiết kiệm", type: "mc", q: "Chị của Vy đã đi làm. Mỗi tháng chị để dành một phần tiền lương, phần còn lại dùng cho ăn uống, đi lại và học thêm tiếng Anh. Nhận xét nào đúng về chị?", o: ["Chị biết tiết kiệm và biết lo cho tương lai", "Chị keo kiệt vì không tiêu hết tiền lương", "Chị chưa biết tiết kiệm vì vẫn chi tiền học thêm", "Chị để dành tiền là việc không cần thiết"], x: "Chị chi tiêu cho những việc cần thiết, có cả việc học, và để dành một phần cho lúc cần: đó là biết tiết kiệm, biết lo xa.", lv: 2 },
      { topic: "Tiết kiệm", type: "tf4", q: "Thấy nhiều bạn trong lớp có cặp sách mới, Ngân cũng đòi mẹ mua dù chiếc cặp cũ vẫn còn tốt. Mỗi lời khuyên sau dành cho Ngân đúng hay sai?", o: ["Tiếp tục dùng cặp cũ vì vẫn còn tốt.", "Đòi mẹ mua bằng được để không thua kém các bạn.", "Giữ gìn cặp cũ cẩn thận để dùng được lâu.", "Cố tình làm hỏng cặp cũ để mẹ phải mua cặp mới."], a: [true, false, true, false], x: "a), c) Đúng: dùng tiếp và giữ gìn đồ còn tốt là tiết kiệm. b), d) Sai: chạy theo bạn bè, đòi mua đồ không cần thiết hay cố tình làm hỏng đồ là lãng phí tiền của gia đình.", lv: 3 },
      { topic: "Tiết kiệm", type: "mc", q: "Tổ của Trang được giao làm báo tường chào mừng ngày 26 tháng 3. Cách làm nào vừa đẹp vừa tiết kiệm?", o: ["Tận dụng giấy màu, bìa cũ, chia việc cho từng bạn để làm nhanh", "Mua thật nhiều giấy màu mới, dùng không hết thì bỏ", "Mỗi bạn tự làm một tờ báo riêng rồi chọn một tờ", "Thuê cửa hàng in sẵn cho thật đẹp"], x: "Tận dụng giấy màu, bìa cũ giúp đỡ tốn tiền mua mới; chia việc cho từng bạn giúp làm xong nhanh. Mua thừa rồi bỏ, mỗi bạn làm một tờ hay thuê in đều gây lãng phí.", lv: 3 },
      { topic: "Tiết kiệm", type: "num", q: "Mỗi tuần Duy để dành được 25 000 đồng từ tiền ăn sáng. Duy muốn mua một bộ truyện giá 150 000 đồng. Sau ít nhất bao nhiêu tuần thì Duy để dành đủ tiền mua bộ truyện?", ans: 6, unit: "tuần", x: "150 000 : 25 000 = 6. Sau ít nhất 6 tuần, Duy để dành đủ tiền mua bộ truyện.", lv: 3 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Chị Hoa và chị Lily cùng sống, làm việc ở Hà Nội. Chị Hoa có quốc tịch Việt Nam, chị Lily có quốc tịch Pháp. Nhận xét nào đúng?", o: ["Chỉ chị Hoa là công dân Việt Nam", "Cả hai chị đều là công dân Việt Nam vì cùng sống ở Việt Nam", "Cả hai chị đều không phải công dân Việt Nam", "Chỉ chị Lily là công dân Việt Nam vì làm việc ở Hà Nội"], x: "Quốc tịch cho biết một người là công dân nước nào. Chị Hoa có quốc tịch Việt Nam nên là công dân Việt Nam; chị Lily vẫn là công dân Pháp dù sống, làm việc ở Hà Nội.", lv: 1 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Một người nước ngoài muốn có quốc tịch Việt Nam thì cần:", o: ["Làm thủ tục xin nhập quốc tịch Việt Nam, đáp ứng các điều kiện theo quy định của pháp luật và được cho phép", "Chỉ cần sống ở Việt Nam một vài tháng", "Chỉ cần nói thạo tiếng Việt", "Chỉ cần đặt cho mình một cái tên tiếng Việt"], x: "Người nước ngoài muốn có quốc tịch Việt Nam phải làm đơn xin nhập quốc tịch, đáp ứng các điều kiện do Luật Quốc tịch Việt Nam quy định và được cơ quan nhà nước có thẩm quyền cho phép.", lv: 1 },
      { topic: "Công dân nước Việt Nam", type: "tf4", q: "Theo Luật Quốc tịch Việt Nam, mỗi trường hợp sau có quốc tịch Việt Nam đúng hay sai?", o: ["Em bé sơ sinh bị bỏ rơi, được tìm thấy ở Việt Nam, không rõ cha mẹ là ai.", "Một vận động viên nước ngoài sang Việt Nam thi đấu một tuần.", "Em bé có cha mẹ đều là người nước ngoài, sinh ra khi cha mẹ đang du lịch ở Việt Nam.", "Em bé sinh ra ở Việt Nam, cha mẹ đều là người không quốc tịch nhưng thường trú ở Việt Nam."], a: [true, false, false, true], x: "a), d) Đúng: pháp luật Việt Nam bảo đảm những em bé này có quốc tịch Việt Nam. b), c) Sai: vận động viên vẫn mang quốc tịch nước mình; em bé có cha mẹ đều là người nước ngoài thì không có quốc tịch Việt Nam chỉ vì được sinh ra ở Việt Nam.", lv: 2 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Nhà hàng xóm có em bé mới sinh đã hơn hai tháng mà bố mẹ em bé vẫn chưa đi làm giấy khai sinh vì bận. Em có thể làm gì phù hợp?", o: ["Nhờ bố mẹ mình nhắc nhẹ gia đình hàng xóm sớm đăng kí khai sinh cho em bé", "Không quan tâm vì đó là việc riêng của nhà người ta", "Bảo gia đình hàng xóm chờ đến khi em bé đi học mới cần làm giấy khai sinh", "Tự mình đi làm giấy khai sinh thay cho bố mẹ em bé"], x: "Đăng kí khai sinh là quyền của trẻ em: giấy khai sinh ghi họ tên, ngày sinh, quốc tịch của em bé, giúp em được hưởng các quyền như đi học, khám chữa bệnh. Em có thể nhờ bố mẹ mình nhắc nhẹ gia đình hàng xóm làm sớm.", lv: 3 }
    ]
  },

  /* ---------- GDCD 6 · Kiểm tra cuối năm học (Kết nối tri thức) ----------
     Phạm vi học kì II, ghi ở note: Bài 10–12 (18 câu mỗi đề), ôn Bài 7–9 (7 câu mỗi đề, chữ chủ đề như kho giữa kì II). Câu tự soạn
     (Phiên N22), đối chiếu sách in năm 2026 (Bài 10 trích Hiến pháp năm 2013, sửa đổi, bổ sung năm 2025). Hai đề là kho của đề ngẫu
     nhiên "gdcd6-ck2-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js); hai đề cùng phân bố
     chủ đề và mức như ma trận, nên ô nào cũng có gấp đôi số câu ô đó rút. Cách xếp mức như đề cuối kì I ở đầu file: nhận ra quyền,
     nghĩa vụ, nhóm quyền, bổn phận, số liệu (tuổi, năm) là Biết; nhận xét một ý kiến, giải thích, phân loại trường hợp là Hiểu; xử lí
     tình huống là Vận dụng. Mỗi tình huống chỉ có ở một câu và không trùng tình huống của kho giữa kì II (Bài 7–9) hay của sách (Hưng
     bóc thư, Lan đòi xe máy điện, Quân cho sách, Lan xin đi tham quan…). Câu ở hai ô khác nhau, cả các câu của một ô rút từ 2 câu
     trở lên, có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời giải không ghi sẵn đáp án của câu khác. Câu về quốc
     tịch đúng với Luật Quốc tịch Việt Nam sửa đổi năm 2025 (các trường hợp sách trích không đổi). */
  "gdcd6-ck2-de1": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, cuối năm học: Bài 10 Quyền và nghĩa vụ cơ bản của công dân; Bài 11 Quyền cơ bản của trẻ em; Bài 12 Thực hiện quyền trẻ em; ôn Bài 7 Ứng phó với tình huống nguy hiểm, Bài 8 Tiết kiệm, Bài 9 Công dân nước Cộng hoà xã hội chủ nghĩa Việt Nam. Có trường chỉ kiểm tra Bài 10–12, phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "match", q: "Nối mỗi quyền cơ bản của công dân với nhóm quyền phù hợp.", l: ["Quyền tự do ngôn luận, tự do báo chí", "Quyền bất khả xâm phạm về chỗ ở", "Quyền có việc làm", "Quyền nghiên cứu khoa học và công nghệ"], r: ["Nhóm quyền chính trị", "Nhóm quyền dân sự", "Nhóm quyền về kinh tế", "Nhóm quyền văn hoá, xã hội"], x: "Tự do ngôn luận, báo chí thuộc nhóm quyền chính trị; bất khả xâm phạm về chỗ ở thuộc nhóm quyền dân sự; có việc làm thuộc nhóm quyền về kinh tế; nghiên cứu khoa học và công nghệ thuộc nhóm quyền văn hoá, xã hội.", lv: 1 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Việc làm nào dưới đây thể hiện quyền tự do kinh doanh của công dân?", o: ["Chị Hạnh mở một cửa hàng bán văn phòng phẩm gần trường", "Anh Tuấn đi bỏ phiếu bầu đại biểu Hội đồng nhân dân xã", "Bà Lụa đến chùa lễ Phật vào ngày rằm cùng các con cháu", "Ông Tư viết thư góp ý gửi Uỷ ban nhân dân phường mình"], x: "Mở cửa hàng buôn bán là thực hiện quyền tự do kinh doanh. Đi bầu cử, đi lễ chùa, góp ý với chính quyền là thực hiện những quyền khác của công dân.", lv: 1 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Quang nói: “Đi học là quyền của mình, nên mình thích thì đi, không thích thì nghỉ.” Nhận xét nào về ý kiến của Quang là đúng?", o: ["Chưa đúng: học tập vừa là quyền, vừa là nghĩa vụ của công dân", "Đúng: học sinh được nghỉ học bất cứ hôm nào mình không thích đi", "Đúng: chỉ người lớn mới phải làm nghĩa vụ, học sinh thì chưa", "Chưa đúng: đi học là nghĩa vụ, không phải là quyền"], x: "Theo Hiến pháp, công dân có quyền và nghĩa vụ học tập. Quang được đi học, đồng thời phải chăm chỉ học, không được tuỳ ý nghỉ.", lv: 2 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "tf4", q: "Mỗi việc làm sau là thực hiện nghĩa vụ cơ bản của công dân đúng hay sai?", o: ["Bà Ba đi tập dưỡng sinh mỗi sáng ở công viên.", "Chú Tâm kê khai, nộp thuế đầy đủ cho tiệm sửa xe của mình.", "Anh Bình chuyển đến thành phố khác để sống và làm việc.", "Người đi xe máy dừng lại khi gặp đèn đỏ."], a: [false, true, false, true], x: "b), d) Đúng: nộp thuế, tuân theo pháp luật (như chấp hành luật giao thông) là nghĩa vụ cơ bản của công dân. a), c) Sai: tập thể dục, chuyển đến nơi khác sống là những việc mỗi người được tự do lựa chọn, không phải nghĩa vụ.", lv: 2 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Xưởng mộc nhà Hưng thải nhiều bụi gỗ, mùn cưa ra đường làng, khiến hàng xóm phàn nàn. Hưng nên khuyên bố mẹ làm gì?", o: ["Lắp máy hút bụi, thu gom mùn cưa đúng nơi quy định, giữ sạch môi trường", "Chỉ làm việc vào ban đêm để hàng xóm không nhìn thấy bụi bay ra", "Mặc kệ vì xưởng là của gia đình mình, người khác không được ý kiến", "Đổ hết mùn cưa xuống con mương đầu làng cho nhanh gọn, đỡ tốn công"], x: "Bảo vệ môi trường là nghĩa vụ của mọi công dân. Gia đình Hưng được quyền làm ăn, nhưng phải xử lí bụi, chất thải để không làm ô nhiễm môi trường, không ảnh hưởng đến sức khoẻ của hàng xóm.", lv: 3 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "tf4", q: "Khoa mượn điện thoại của Long, tự ý đọc tin nhắn của Long rồi chụp lại, gửi cho các bạn trong lớp xem. Mỗi nhận xét sau đúng hay sai?", o: ["Khoa đã xâm phạm bí mật đời sống riêng tư, bí mật cá nhân của Long.", "Vì là bạn thân nên Khoa được tự ý đọc tin nhắn của Long.", "Long nên nói rõ với Khoa và nhờ thầy cô, bố mẹ giúp đỡ nếu cần.", "Các bạn nhận được ảnh nên chia sẻ tiếp cho thêm vui."], a: [true, false, true, false], x: "a), c) Đúng: tin nhắn là bí mật riêng tư, người khác không được tự ý xem, chụp, gửi đi; Long nên bình tĩnh nói chuyện với Khoa, nhờ người lớn giúp khi cần. b), d) Sai: dù là bạn thân cũng phải được Long đồng ý; chia sẻ tiếp là tiếp tay cho việc làm sai.", lv: 3 },
      { topic: "Quyền cơ bản của trẻ em", type: "fill", q: "Theo Luật Trẻ em của nước ta, trẻ em là người dưới ___ tuổi.", ans: ["16"], x: "Theo Luật Trẻ em năm 2016, trẻ em là người dưới 16 tuổi.", lv: 1 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Năm 1990, Việt Nam phê chuẩn Công ước của Liên hợp quốc về quyền trẻ em. Điều nào đúng về sự kiện này?", o: ["Việt Nam phê chuẩn sớm nhất châu Á và thứ hai trên thế giới", "Việt Nam phê chuẩn muộn nhất châu Á và trên thế giới", "Việt Nam là nước đầu tiên trên thế giới soạn ra Công ước", "Việt Nam phê chuẩn để Công ước chỉ áp dụng cho trẻ em thành phố"], x: "Việt Nam phê chuẩn Công ước ngày 20/2/1990, sớm nhất châu Á và chỉ sau một quốc gia trên thế giới. Việc này cho thấy nước ta rất quan tâm đến trẻ em.", lv: 1 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Bổn phận của trẻ em đối với gia đình là:", o: ["Quan tâm, vâng lời ông bà, cha mẹ, đỡ đần việc nhà hợp với sức mình", "Đòi bố mẹ phải mua cho mình mọi thứ mình thích, kể cả đồ đắt tiền", "Chỉ lo việc học của mình, không cần quan tâm đến người thân trong nhà", "Làm theo ý mình, không cần nghe lời khuyên bảo của ông bà, cha mẹ"], x: "Trẻ em có quyền và cũng có bổn phận. Với gia đình, trẻ em cần yêu thương, vâng lời ông bà, cha mẹ, phụ giúp việc nhà vừa sức.", lv: 1 },
      { topic: "Quyền cơ bản của trẻ em", type: "match", q: "Nối mỗi trường hợp với nhóm quyền của trẻ em mà trường hợp đó thể hiện.", l: ["Trẻ nhỏ được ăn uống đủ chất để lớn lên khoẻ mạnh", "Công an giải cứu một em bé bị kẻ xấu bắt cóc", "Trẻ em được xem phim hoạt hình, đọc truyện phù hợp với lứa tuổi", "Học sinh được góp ý về thực đơn bữa ăn bán trú"], r: ["Nhóm quyền được sống còn", "Nhóm quyền được bảo vệ", "Nhóm quyền được phát triển", "Nhóm quyền được tham gia"], x: "Được nuôi dưỡng, ăn uống đủ chất thuộc nhóm quyền được sống còn; được bảo vệ khỏi bắt cóc, mua bán thuộc nhóm quyền được bảo vệ; được vui chơi, giải trí, tiếp nhận thông tin thuộc nhóm quyền được phát triển; được bày tỏ ý kiến về việc liên quan đến mình thuộc nhóm quyền được tham gia.", lv: 2 },
      { topic: "Quyền cơ bản của trẻ em", type: "tf4", q: "Mai cho rằng: “Trẻ em có quyền bày tỏ ý kiến, nên khi không đồng ý với bố mẹ, mình có thể cãi lại, nói to tiếng.” Mỗi nhận xét sau đúng hay sai?", o: ["Mai hiểu chưa đúng về quyền bày tỏ ý kiến của trẻ em.", "Khi bày tỏ ý kiến, cần lễ phép, tôn trọng người nghe.", "Đã là quyền của trẻ em thì nói với người lớn thế nào cũng được.", "Bố mẹ không cần lắng nghe ý kiến của con."], a: [true, true, false, false], x: "a), b) Đúng: trẻ em được bày tỏ ý kiến, nguyện vọng của mình, nhưng phải lễ phép với người lớn: đó cũng là bổn phận của trẻ em. c), d) Sai: cãi lại, nói to tiếng với bố mẹ là thiếu lễ phép; bố mẹ nên lắng nghe, tôn trọng ý kiến của con.", lv: 2 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Trên đường đi học, Hằng thường gặp một cậu bé khoảng 9 tuổi phải đi bán vé số đến tối muộn, không được đến trường. Hằng nên làm gì?", o: ["Kể với bố mẹ, thầy cô hoặc gọi Tổng đài 111 để cậu bé được giúp đỡ", "Mua hết số vé số còn lại mỗi tối để cậu bé được về nhà sớm", "Không quan tâm vì việc đi bán vé số là chuyện riêng của nhà cậu bé", "Rủ cậu bé bỏ nhà đi theo mình để khỏi phải đi bán vé số nữa"], x: "Cậu bé phải làm việc kiếm tiền quá sức, không được đi học: quyền được bảo vệ, được học tập của em chưa được bảo đảm. Hằng nên báo cho người lớn hoặc gọi Tổng đài quốc gia bảo vệ trẻ em 111 (miễn phí) để các cơ quan có trách nhiệm giúp đỡ em.", lv: 3 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Hành vi nào dưới đây thể hiện việc thực hiện đúng quyền trẻ em?", o: ["Bố mẹ đưa con đi khám, chữa bệnh khi con bị sốt cao", "Bắt con nghỉ học ở nhà trông em để bố mẹ đi làm", "Bắt con làm hết việc nhà, không còn thời gian học bài", "Không cho con chơi với bất kì bạn bè nào"], x: "Đưa con đi khám, chữa bệnh khi con ốm là trách nhiệm của bố mẹ, giúp con được chăm sóc sức khoẻ. Ba việc còn lại làm con không được học tập, vui chơi, kết bạn như mọi trẻ em khác.", lv: 1 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Ý kiến nào dưới đây đúng về người bạo hành, xâm hại trẻ em?", o: ["Dù là ai, kể cả người thân, cũng bị xử lí theo pháp luật", "Xin lỗi gia đình của trẻ em là đủ, không bị xử lí gì thêm", "Nếu là cha mẹ, ông bà của trẻ thì không bị xử lí gì", "Trẻ em không bị thương nặng thì người vi phạm được bỏ qua"], x: "Mọi hành vi bạo hành, xâm hại trẻ em đều vi phạm pháp luật và bị xử lí nghiêm, có thể bị phạt tù, kể cả khi người vi phạm là cha mẹ, người thân của trẻ.", lv: 1 },
      { topic: "Thực hiện quyền trẻ em", type: "tf4", q: "Mỗi hành vi sau là vi phạm quyền trẻ em đúng hay sai?", o: ["Bố mẹ cho con đi học vẽ vào dịp nghỉ hè.", "Một người lớn lợi dụng trẻ em để đi trộm cắp.", "Cô chú đưa cháu đi xem triển lãm tranh thiếu nhi.", "Người lớn rủ rê trẻ em cá cược bóng đá qua mạng."], a: [false, true, false, true], x: "b), d) Đúng: lợi dụng trẻ em làm việc phạm pháp, rủ rê trẻ em cá cược là vi phạm quyền trẻ em. a), c) Sai: đó là những việc làm tốt, giúp trẻ em được học hỏi, vui chơi.", lv: 2 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Trường của Ngân lắp camera ở hành lang, có bác bảo vệ trực ở cổng và không cho người lạ vào trường trong giờ học. Những việc đó thể hiện trách nhiệm nào của nhà trường?", o: ["Giữ an toàn cho học sinh trong thời gian ở trường", "Theo dõi để phạt học sinh mỗi khi mắc lỗi", "Hạn chế quyền tự do đi lại của học sinh", "Quyết định thay học sinh mọi việc trong học tập"], x: "Một trách nhiệm của nhà trường là giữ cho học sinh được học tập, vui chơi an toàn. Camera, bác bảo vệ, việc không cho người lạ vào trường giúp ngăn kẻ xấu làm hại học sinh.", lv: 2 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Một chú quen ở gần nhà hay cho Hoa quà, rồi rủ Hoa sang nhà chú chơi lúc bố mẹ Hoa vắng nhà và dặn: “Chuyện này đừng kể với ai nhé.” Hoa nên làm gì?", o: ["Không sang, kể ngay với bố mẹ hoặc thầy cô", "Sang chơi một lát vì chú là người quen, hay cho quà", "Giữ bí mật như lời chú dặn để chú khỏi buồn", "Rủ thêm một bạn cùng sang xem chú định làm gì"], x: "Người lớn tử tế không bắt trẻ em giấu bố mẹ; lời dặn “đừng kể với ai” là dấu hiệu nguy hiểm. Để tự bảo vệ mình trước nguy cơ bị xâm hại, Hoa không đi, không ở riêng với người đó và kể ngay với bố mẹ hoặc thầy cô.", lv: 3 },
      { topic: "Thực hiện quyền trẻ em", type: "tf4", q: "Lớp 6B có bạn Phúc mới chuyển đến. Một nhóm bạn lập nhóm trò chuyện trên mạng để chê bai, nói xấu Phúc. Mỗi việc làm sau của các bạn trong lớp đúng hay sai?", o: ["Không tham gia nói xấu và nhắc nhóm bạn dừng lại.", "Báo với cô chủ nhiệm để cô giúp cả lớp hiểu, gần gũi Phúc hơn.", "Thả biểu tượng cười vào các tin nhắn nói xấu cho vui.", "Rủ Phúc cùng tham gia các hoạt động, nhóm học tập của lớp."], a: [true, true, false, true], x: "a), b), d) Đúng: học sinh cần ủng hộ việc làm đúng, phê phán việc làm xúc phạm bạn, giúp bạn mới hoà nhập. c) Sai: hưởng ứng lời nói xấu là tiếp tay làm tổn thương bạn.", lv: 3 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Số điện thoại 112 dùng để làm gì?", o: ["Nhờ tìm kiếm, cứu người gặp nạn", "Báo tin có kẻ trộm, kẻ cướp", "Gọi xe cấp cứu đưa người ốm đi viện", "Hỏi giá cả hàng hoá ở chợ"], x: "112 là số gọi khi cần tìm kiếm, cứu nạn, nhất là lúc có thiên tai như lũ quét. Có kẻ trộm, cướp: gọi 113; có cháy hoặc cần cứu nạn, cứu hộ: gọi 114; cần cấp cứu y tế: gọi 115.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Trước chuyến đi biển, bố dặn Lâm: “Lỡ rơi xuống chỗ nước sâu thì đừng vùng vẫy loạn xạ.” Vì sao bố dặn vậy?", o: ["Vùng vẫy mạnh làm cơ thể nhanh đuối sức, dễ sặc nước và chìm", "Vùng vẫy làm nước bắn lên nên người trên bờ không nhìn thấy", "Vùng vẫy làm cơ thể nổi lên quá nhanh nên khó giữ thăng bằng", "Vùng vẫy làm ướt quần áo của người đến cứu mình"], x: "Hoảng loạn, vùng vẫy mạnh khiến cơ thể mau mệt, dễ uống phải nước và chìm. Giữ bình tĩnh, thả lỏng người giúp cơ thể dễ nổi; cử động tay chân nhịp nhàng để giữ mũi, miệng trên mặt nước và kêu cứu.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Cả nhà Tín đang nướng ngô ngoài sân thì vạt áo của Tín bị bén lửa. Tín nên làm gì ngay?", o: ["Nằm xuống đất, lăn tròn để dập tắt lửa", "Chạy thật nhanh để gió thổi tắt lửa", "Đứng yên một chỗ chờ lửa tự tắt", "Dùng tay không đập mạnh vào chỗ đang cháy"], x: "Chạy làm gió thổi mạnh vào lửa, lửa càng bùng to. Nằm xuống và lăn tròn trên mặt đất giúp đè tắt lửa; đồng thời gọi to để người lớn đến giúp.", lv: 3 },
      { topic: "Tiết kiệm", type: "mc", q: "Câu tục ngữ “Của bền tại người” khuyên chúng ta điều gì?", o: ["Đồ dùng bền hay không là do người dùng giữ gìn", "Đồ dùng đắt tiền thì lúc nào cũng bền, dùng thế nào cũng được", "Muốn đồ dùng bền thì phải mua thật nhiều để thay đổi", "Đồ dùng của người khác thì không cần phải giữ gìn"], x: "“Của bền tại người” nghĩa là đồ dùng bền lâu hay chóng hỏng là do cách người dùng giữ gìn. Biết bảo quản đồ dùng cẩn thận là một biểu hiện của tiết kiệm.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Mẹ định mua cho Nga một chiếc mũ bảo hiểm để đội khi ngồi sau xe máy. Chiếc mũ rẻ hơn hẳn các mũ khác, vỏ mỏng, nhẹ tênh, bên trong không có lớp xốp. Nga nên nói gì với mẹ?", o: ["Nên chọn mũ có tem kiểm định, rõ nguồn gốc, dù giá cao hơn một chút", "Nên mua liền ba chiếc mũ rẻ để thay dần mỗi khi chiếc cũ bị hỏng", "Nên mua chiếc mũ đắt nhất cửa hàng để được các bạn trong lớp khen", "Không cần đội mũ khi chỉ ngồi sau xe máy, như vậy đỡ tốn tiền hơn"], x: "Tiết kiệm là chi tiêu hợp lí, không phải cứ chọn đồ rẻ nhất. Mũ bảo hiểm kém chất lượng vừa không bảo vệ được người đội, vừa nhanh hỏng, phải mua lại nhiều lần nên còn tốn hơn.", lv: 3 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Quốc tịch thể hiện mối quan hệ giữa những ai?", o: ["Giữa một người với Nhà nước của nước mình", "Giữa một người với gia đình, dòng họ của mình", "Giữa một người với trường học, nơi làm việc của mình", "Giữa một người với bạn bè, hàng xóm của mình"], x: "Quốc tịch gắn một người với Nhà nước của nước mình: Nhà nước bảo vệ quyền lợi của người đó, người đó thực hiện nghĩa vụ với Nhà nước.", lv: 1 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Khôi 11 tuổi, có quốc tịch Việt Nam. Khôi hỏi: “Em chưa có thẻ căn cước, vậy em đã là công dân Việt Nam chưa?” Câu trả lời nào đúng?", o: ["Khôi đã là công dân Việt Nam, dù chưa có thẻ căn cước", "Khôi chưa là công dân vì chưa đủ 18 tuổi", "Khôi chỉ là công dân khi đã làm xong thẻ căn cước", "Khôi mới là thành viên của gia đình, chưa là công dân"], x: "Khôi có quốc tịch Việt Nam nên đã là công dân Việt Nam. Thẻ căn cước chỉ là giấy tờ ghi thông tin của công dân; tuổi hay việc chưa làm thẻ không thay đổi điều đó.", lv: 2 }
    ]
  },

  "gdcd6-ck2-de2": {
    note: "Giáo dục công dân 6, sách Kết nối tri thức, cuối năm học: Bài 10 Quyền và nghĩa vụ cơ bản của công dân; Bài 11 Quyền cơ bản của trẻ em; Bài 12 Thực hiện quyền trẻ em; ôn Bài 7 Ứng phó với tình huống nguy hiểm, Bài 8 Tiết kiệm, Bài 9 Công dân nước Cộng hoà xã hội chủ nghĩa Việt Nam. Có trường chỉ kiểm tra Bài 10–12, phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Quyền cơ bản của công dân là:", o: ["Những điều công dân được hưởng, được làm và được pháp luật bảo vệ", "Những việc công dân bắt buộc phải làm theo yêu cầu của Nhà nước", "Những điều mỗi người tự đặt ra rồi tự quyết định cho riêng mình", "Những quy định riêng mà từng gia đình, dòng họ tự đặt ra"], x: "Quyền là những điều công dân được hưởng, được làm mà Nhà nước công nhận, bảo vệ. Còn những việc pháp luật bắt buộc công dân phải làm là nghĩa vụ.", lv: 1 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Việc làm nào dưới đây là thực hiện nghĩa vụ cơ bản của công dân?", o: ["Thanh niên đủ điều kiện lên đường nhập ngũ khi có lệnh gọi", "Gia đình anh Phong rủ nhau đi xem phim vào dịp cuối tuần", "Ông Năm tham gia câu lạc bộ cờ tướng của phường mỗi tối", "Chị Mai trồng thêm mấy chậu hoa trên ban công nhà mình"], x: "Thực hiện nghĩa vụ quân sự để bảo vệ Tổ quốc là một nghĩa vụ cơ bản của công dân. Xem phim, chơi cờ, trồng hoa là những việc mỗi người tự do lựa chọn.", lv: 1 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Tùng viết lên bảng lớp những lời lẽ chế giễu, xúc phạm bạn Quân để cả lớp cùng đọc. Việc làm của Tùng đã xâm phạm quyền nào của Quân?", o: ["Quyền được pháp luật bảo hộ về danh dự, nhân phẩm", "Quyền tự do tín ngưỡng, tôn giáo của công dân", "Quyền tham gia quản lí nhà nước và xã hội", "Quyền được hưởng chế độ bảo đảm an sinh xã hội"], x: "Chế giễu, xúc phạm người khác trước đông người làm tổn hại danh dự, nhân phẩm của họ. Đây là xâm phạm quyền được pháp luật bảo hộ về danh dự, nhân phẩm.", lv: 2 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "tf4", q: "Mỗi ý sau về quyền và nghĩa vụ của công dân đúng hay sai?", o: ["Ông Minh là giám đốc, bác Hải là nông dân; khi đi bầu cử, mỗi người đều có một lá phiếu như nhau.", "Người có nhiều tiền được hưởng nhiều quyền hơn người nghèo.", "Hàng xóm được mở nhạc thật to lúc nửa đêm vì đó là quyền của họ.", "Học sinh người dân tộc thiểu số được đi học, được khám chữa bệnh như mọi học sinh khác."], a: [true, false, false, true], x: "a), d) Đúng: trước pháp luật, mọi công dân đều bình đẳng, không phân biệt giàu nghèo, nghề nghiệp, dân tộc. b) Sai: giàu hay nghèo, công dân đều có quyền như nhau. c) Sai: ai cũng có quyền của mình nhưng không được xâm phạm quyền và lợi ích của người khác, như giấc ngủ của hàng xóm.", lv: 2 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Chị gái của Hà lần đầu được đi bầu cử đại biểu Quốc hội nhưng định ở nhà vì nghĩ “một lá phiếu chẳng thay đổi được gì”. Hà nên nói gì với chị?", o: ["Mỗi lá phiếu đều góp phần chọn người xứng đáng; chị nên tự đi bầu", "Chị không cần đi, cứ nhờ người khác cầm phiếu bầu hộ mình là được rồi", "Chị chỉ nên đi bầu nếu được trả tiền công cho buổi đi bầu hôm đó", "Chị nên ở nhà, vì việc bầu cử chỉ dành cho những người đã lớn tuổi"], x: "Bầu cử là một quyền quan trọng của công dân. Mỗi lá phiếu góp phần chọn ra những người đại diện xứng đáng cho nhân dân; công dân nên tự mình đi bầu, không nhờ người khác bỏ phiếu hộ.", lv: 3 },
      { topic: "Quyền và nghĩa vụ cơ bản của công dân", type: "mc", q: "Nhà Thảo có hai chị em. Bố mẹ định chỉ cho em trai đi học thêm tiếng Anh vì nghĩ “con gái không cần học nhiều”. Thảo nên làm gì?", o: ["Lễ phép nói với bố mẹ rằng con trai, con gái đều có quyền học tập như nhau", "Giận dỗi, không nói chuyện với bố mẹ cho đến khi bố mẹ chịu đồng ý", "Im lặng chấp nhận vì nghĩ con gái thì lúc nào cũng phải nhường em trai", "Đòi em trai phải nhường suất học thêm tiếng Anh cho mình mới được"], x: "Công dân nam, nữ bình đẳng; con trai, con gái đều có quyền học tập như nhau. Thảo nên lễ phép trình bày với bố mẹ, có thể nhờ ông bà, thầy cô nói giúp.", lv: 3 },
      { topic: "Quyền cơ bản của trẻ em", type: "fill", q: "Công ước của Liên hợp quốc về quyền trẻ em được Đại hội đồng Liên hợp quốc thông qua vào năm ___.", ans: ["1989"], x: "Công ước được Liên hợp quốc thông qua ngày 20/11/1989; đây là văn bản quốc tế nêu các quyền cơ bản của trẻ em.", lv: 1 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Các quyền cơ bản của trẻ em giúp ích gì cho trẻ em?", o: ["Giúp trẻ em được sống an toàn, được học hành, vui chơi", "Giúp trẻ em không phải làm bất cứ việc gì trong gia đình", "Giúp trẻ em được làm mọi điều mình muốn, không ai được nhắc", "Chỉ giúp ích cho trẻ em ở những nước giàu có"], x: "Được chăm sóc, bảo vệ, học tập, vui chơi và được lắng nghe, trẻ em lớn lên vui vẻ, hiểu biết, tự tin.", lv: 1 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Bổn phận của trẻ em đối với quê hương, đất nước là:", o: ["Gắn bó với nơi mình sinh ra, gìn giữ phong tục tốt đẹp của dân tộc", "Chỉ cần học thật giỏi, không cần quan tâm đến quê hương, đất nước", "Chê bai, bỏ đi những phong tục cổ truyền tốt đẹp của dân tộc", "Chỉ yêu thích và học theo văn hoá của nước ngoài, chê văn hoá nước mình"], x: "Trẻ em có bổn phận yêu quê hương, đất nước, yêu đồng bào; trân trọng, giữ gìn nét đẹp văn hoá của dân tộc; góp sức xây dựng, bảo vệ Tổ quốc phù hợp với lứa tuổi.", lv: 1 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Bố mẹ Tú đi làm ăn xa, gửi Tú cho một người họ hàng. Người này thường để Tú ở nhà một mình nhiều ngày, ăn uống thất thường, không ai chăm lo. Quyền nào của Tú chưa được bảo đảm?", o: ["Quyền được chăm sóc, nuôi dưỡng", "Quyền có quốc tịch", "Quyền tự do tín ngưỡng, tôn giáo", "Quyền được bày tỏ ý kiến, nguyện vọng"], x: "Trẻ em có quyền được chăm sóc, nuôi dưỡng để lớn lên khoẻ mạnh. Người nhận trông Tú đã bỏ mặc em, nên quyền đó của Tú chưa được bảo đảm.", lv: 2 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Vì sao pháp luật có những quy định riêng để bảo vệ trẻ em khỏi bị bóc lột, xâm hại?", o: ["Vì trẻ em còn nhỏ, chưa đủ sức và hiểu biết để tự bảo vệ mình", "Vì trẻ em không cần được học tập, vui chơi như những người khác", "Vì trẻ em đã đủ sức làm mọi việc nặng nhọc như người lớn", "Vì chỉ có trẻ em mới phải tuân theo các quy định của pháp luật"], x: "Trẻ em đang lớn, sức khoẻ, hiểu biết, kinh nghiệm sống còn ít nên khó tự bảo vệ mình, dễ bị kẻ xấu lợi dụng, làm hại; vì vậy cần được người lớn và pháp luật bảo vệ.", lv: 2 },
      { topic: "Quyền cơ bản của trẻ em", type: "mc", q: "Trong buổi sinh nhật của một người bạn, Khánh được một anh lớn tuổi hơn mời hút thử thuốc lá điện tử “cho biết”. Khánh nên làm gì?", o: ["Từ chối dứt khoát, tránh xa và kể với bố mẹ hoặc thầy cô", "Hút thử một lần cho biết rồi thôi, không sao cả", "Nhận lấy rồi mang về nhà cất đi để dùng sau", "Giữ bí mật với bố mẹ để không làm mất vui buổi sinh nhật"], x: "Thuốc lá điện tử chứa chất gây nghiện, có hại cho sức khoẻ và bị pháp luật cấm. Trẻ em có quyền được bảo vệ khỏi các chất gây nghiện; Khánh cần từ chối dứt khoát và báo cho người lớn.", lv: 3 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Việc thực hiện quyền trẻ em là trách nhiệm của ai?", o: ["Gia đình, nhà trường, xã hội và cả chính trẻ em", "Gia đình và nhà trường, xã hội không cần tham gia", "Nhà nước và xã hội, trẻ em không cần tham gia", "Bố mẹ và thầy cô, người khác không được can thiệp"], x: "Thực hiện quyền trẻ em là việc của mọi người: bố mẹ, người thân, thầy cô, chính quyền và cả xã hội; chính các em cũng cần hiểu và chủ động thực hiện quyền của mình.", lv: 1 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Việc làm nào dưới đây là trách nhiệm của gia đình trong việc thực hiện quyền trẻ em?", o: ["Làm giấy khai sinh cho con đúng thời hạn", "Bắt con làm việc nặng để kiếm thêm tiền", "Để con tự đi tắm sông một mình", "Quyết định mọi việc của con mà không hỏi ý kiến con"], x: "Gia đình có trách nhiệm làm giấy khai sinh đúng hạn, lo cho con ăn học, giữ con an toàn. Ba việc còn lại đều vi phạm quyền trẻ em hoặc đặt trẻ em vào nguy hiểm.", lv: 1 },
      { topic: "Thực hiện quyền trẻ em", type: "tf4", q: "Xã của Bình có nhiều việc làm liên quan đến thiếu nhi. Mỗi việc làm sau giúp bảo đảm quyền trẻ em đúng hay sai?", o: ["Để các quán ăn bán rượu bia cho học sinh.", "Xây sân chơi, thư viện mở cửa miễn phí cho thiếu nhi.", "Mở lớp dạy bơi an toàn cho thiếu nhi vào dịp hè.", "Cho phép bán những đồ chơi nguy hiểm ở cổng trường."], a: [false, true, true, false], x: "b), c) Đúng: đây là những việc chính quyền, xã hội làm để trẻ em có nơi vui chơi, học hỏi an toàn. a), d) Sai: bán rượu bia cho học sinh, bán đồ chơi nguy hiểm ở cổng trường là làm hại trẻ em.", lv: 2 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Mỗi năm, trường của Hoà đều mời bác sĩ đến khám mắt, khám răng cho học sinh. Việc làm đó thể hiện điều gì?", o: ["Nhà trường chăm lo sức khoẻ cho học sinh", "Nhà trường muốn học sinh được nghỉ học nhiều hơn", "Nhà trường muốn chọn bạn khoẻ nhất đi thi thể thao", "Nhà trường muốn bán thêm thuốc cho học sinh"], x: "Mời bác sĩ khám mắt, khám răng định kì là nhà trường lo cho sức khoẻ của học sinh: đó là một trách nhiệm của nhà trường đối với trẻ em. Khám sớm giúp phát hiện và chữa kịp thời các bệnh về mắt, răng.", lv: 2 },
      { topic: "Thực hiện quyền trẻ em", type: "mc", q: "Ngọc nhận ra mình hay nói chuyện riêng, làm việc riêng trong giờ học, đã nhiều lần bị nhắc. Ngọc nên làm gì?", o: ["Chú ý nghe giảng, tự ghi lại lỗi mỗi ngày để sửa dần", "Chờ lên lớp trên rồi mới thay đổi cho dễ", "Chỉ giữ trật tự trong những tiết có thầy cô nghiêm khắc", "Nghĩ rằng trẻ em chỉ có quyền, không cần làm bổn phận"], x: "Tuân theo nội quy nhà trường, kính trọng thầy cô là bổn phận của trẻ em. Tự nhận ra điều chưa tốt rồi sửa dần mỗi ngày là cách thực hiện tốt bổn phận đó.", lv: 3 },
      { topic: "Thực hiện quyền trẻ em", type: "tf4", q: "Sân chơi gần nhà Vy bị biến thành bãi để xe, thiếu nhi trong khu phố không còn chỗ vui chơi. Mỗi việc làm sau của Vy và các bạn đúng hay sai?", o: ["Ra đường lớn chơi đá bóng thay cho sân chơi.", "Tự ý dời các xe máy ra khỏi sân để có chỗ chơi.", "Cùng viết thư, nhờ bố mẹ gửi tổ dân phố đề nghị dành lại sân chơi.", "Kể với thầy cô để được hướng dẫn cách đề đạt nguyện vọng."], a: [false, false, true, true], x: "c), d) Đúng: trẻ em được bày tỏ nguyện vọng về những việc liên quan đến mình, bằng cách phù hợp, nhờ người lớn giúp đỡ. a), b) Sai: chơi ở đường lớn rất nguy hiểm; tự ý dời xe của người khác là việc làm sai.", lv: 3 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Trời đang có mưa dông, sấm sét và em đang ở trong nhà. Việc nên làm là:", o: ["Tắt ti vi, máy tính, rút điện thoại đang sạc ra khỏi ổ điện", "Ra sân đứng xem sấm chớp cho thật rõ, rồi chụp ảnh lại", "Mở toang cửa sổ rồi đứng sát cửa để hóng gió cho mát", "Trèo lên mái nhà để chỉnh lại ăng-ten ti vi cho rõ hình"], x: "Sét có thể theo dây điện, dây ăng-ten vào nhà, nên khi có dông cần ngắt các đồ dùng điện, không đứng gần cửa sổ, không ra ngoài trời hay leo lên chỗ cao.", lv: 1 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Ổ điện ở phòng khách nhà Mai bị chập, bốc cháy. Mai cùng em chạy ra ngoài, vừa đi vừa khép các cửa lại sau lưng. Việc khép cửa có tác dụng gì?", o: ["Làm chậm lửa, khói lan theo mình ra lối thoát", "Giữ đồ đạc trong nhà không bị người khác lấy mất", "Ngăn lực lượng cứu hoả vào nhà làm hỏng đồ đạc", "Giữ cho căn phòng ấm hơn khi mọi người đã ra ngoài"], x: "Khép cửa trên đường thoát ra làm lửa, khói lan chậm sang các phòng khác, cho mọi người thêm thời gian thoát ra và cho lực lượng chữa cháy kịp đến.", lv: 2 },
      { topic: "Ứng phó với tình huống nguy hiểm", type: "mc", q: "Sau nhiều ngày mưa lớn, nhà Duy ở dưới chân một quả đồi thấy sườn đồi có vết nứt, đất đá bắt đầu lăn xuống. Gia đình Duy nên làm gì?", o: ["Nhanh chóng rời đến nơi an toàn và báo cho chính quyền địa phương", "Ở lại trong nhà, đóng chặt cửa chờ đến khi mưa tạnh hẳn", "Trèo lên sườn đồi để xem vết nứt dài bao nhiêu mét", "Dọn đất đá trước cửa nhà rồi sinh hoạt bình thường như mọi ngày"], x: "Vết nứt trên sườn đồi, đất đá lăn xuống sau mưa lớn là dấu hiệu sắp sạt lở đất. Cần rời ngay khỏi vùng nguy hiểm đến nơi an toàn và báo cho chính quyền để được hỗ trợ.", lv: 3 },
      { topic: "Tiết kiệm", type: "mc", q: "Câu ca dao “Ai ơi bưng bát cơm đầy, Dẻo thơm một hạt, đắng cay muôn phần” nhắc nhở chúng ta điều gì?", o: ["Quý trọng hạt gạo và công sức người làm ra, không để lãng phí", "Nên ăn thật nhiều cơm trong mỗi bữa để cơ thể khoẻ mạnh", "Cơm dẻo thơm là nhờ được nấu bằng những chiếc nồi đắt tiền", "Chỉ có người nông dân mới cần phải tiết kiệm cơm gạo"], x: "Để có bát cơm dẻo thơm, người nông dân phải vất vả “đắng cay muôn phần”. Câu ca dao nhắc ta quý trọng thành quả lao động, không lãng phí cơm gạo: đó là một biểu hiện của tiết kiệm.", lv: 1 },
      { topic: "Tiết kiệm", type: "mc", q: "Tuấn có nhiều quần áo cũ còn tốt nhưng đã mặc chật. Cách làm nào vừa tiết kiệm vừa có ích?", o: ["Giặt sạch rồi tặng em nhỏ hoặc gửi quyên góp cho người cần", "Vứt hết vào thùng rác cho tủ quần áo được gọn gàng, sạch sẽ", "Đốt đi để lấy chỗ cất những bộ quần áo mới vừa mua về", "Cất kín trong tủ thật lâu dù không còn ai mặc đến nữa"], x: "Quần áo còn tốt mà mình không mặc vừa nữa thì đem tặng, quyên góp để người khác dùng tiếp: vừa không lãng phí, vừa giúp đỡ được người khác.", lv: 3 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Khi ra nước ngoài, giấy tờ nào chứng nhận một người là công dân Việt Nam?", o: ["Hộ chiếu", "Thẻ học sinh", "Thẻ thư viện", "Vé máy bay"], x: "Hộ chiếu do Nhà nước cấp cho công dân để đi ra nước ngoài; trong hộ chiếu có ghi quốc tịch của người mang. Thẻ học sinh, thẻ thư viện, vé máy bay không cho biết một người mang quốc tịch nước nào.", lv: 1 },
      { topic: "Công dân nước Việt Nam", type: "mc", q: "Bà Lan sinh ra ở Huế, sau đó sang Ca-na-đa sinh sống. Nay bà đã nhập quốc tịch Ca-na-đa và không còn quốc tịch Việt Nam. Hè này bà về thăm quê. Nhận xét nào đúng?", o: ["Bà Lan là công dân Ca-na-đa, không còn là công dân Việt Nam", "Bà Lan vẫn là công dân Việt Nam vì bà sinh ra ở Huế", "Bà Lan lại là công dân Việt Nam trong những ngày về quê", "Bà Lan là công dân cả hai nước vì nói được hai thứ tiếng"], x: "Bà Lan mang quốc tịch Ca-na-đa, không còn quốc tịch Việt Nam, nên bà là công dân Ca-na-đa. Nơi sinh hay việc về thăm quê không làm thay đổi quốc tịch của bà.", lv: 2 }
    ]
  }
});
